INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G5.NATURA.ELEMENTS_OF_A_MAP.MAP_ELEMENTS.M_EM_SCALE_KEY', 'SOCI.G5.NATURA.ELEMENTS_OF_A_MAP.MAP_ELEMENTS', 'Mixes up the scale and the key (thinks the key shows how far apart places are).', '{"question":"Which part of a map shows how far apart two towns are on the ground?","wrong_answer":"The key","correct_answer":"The scale"}'::jsonb, 'The child knows both are boxes in a corner and treats them as one thing.', 'Offer "The key" next to the right answer and ask the question again in a new context.', 'Use a described map: the key lists symbols, the scale turns a ruler distance into ground distance. Ask for one job each.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G5.NATURA.ELEMENTS_OF_A_MAP.MAP_ELEMENTS.M_EM_FRAME_TITLE', 'SOCI.G5.NATURA.ELEMENTS_OF_A_MAP.MAP_ELEMENTS', 'Mixes up the title and the frame (thinks the frame names the map or the title is the border).', '{"question":"Which element tells you what the map is about?","wrong_answer":"The frame","correct_answer":"The title"}'::jsonb, 'Both sit at the edge of the map, so the child links them.', 'Offer "The frame" next to the right answer and ask the question again in a new context.', 'Cover the title and ask what the map is about; then ask what the border is for.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G5.NATURA.ELEMENTS_OF_A_MAP.MAP_ELEMENTS.M_EM_COMPASS_ROLE', 'SOCI.G5.NATURA.ELEMENTS_OF_A_MAP.MAP_ELEMENTS', 'Thinks the compass on a map tells the time or the weather, or shows the symbols.', '{"question":"What does the compass drawn on a map show?","wrong_answer":"The symbols used on the map","correct_answer":"Direction, such as north"}'::jsonb, 'The child has seen the compass as decoration only.', 'Offer "The symbols used on the map" next to the right answer and ask the question again in a new context.', 'Ask the child to find north on the page before using any place name.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G5.NATURA.ELEMENTS_OF_A_MAP.MAP_READING.M_EM_SYMBOL_GUESS', 'SOCI.G5.NATURA.ELEMENTS_OF_A_MAP.MAP_READING', 'Guesses what a symbol means from how it looks instead of reading the key.', '{"question":"The key shows a small triangle for a school. A triangle also looks like a tent. What does the triangle on this map stand for?","wrong_answer":"A tent","correct_answer":"A school"}'::jsonb, 'The child trusts how the symbol looks, not the key.', 'Offer "A tent" next to the right answer and ask the question again in a new context.', 'Change the key so a triangle means a church, then a school, and ask again each time.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G5.NATURA.ELEMENTS_OF_A_MAP.MAP_READING.M_EM_SCALE_IGNORE', 'SOCI.G5.NATURA.ELEMENTS_OF_A_MAP.MAP_READING', 'Reads map distance as ground distance without using the scale (1 cm taken as 1 km).', '{"question":"On a map, 3 cm stands for 30 km. How far apart are two towns that are 2 cm apart on this map?","wrong_answer":"2 km","correct_answer":"20 km"}'::jsonb, 'The child reads the number on the ruler as the ground distance.', 'Offer "2 km" next to the right answer and ask the question again in a new context.', 'Make a scale line on paper and read it together before measuring anything.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G5.NATURA.ELEMENTS_OF_A_MAP.MAP_ELEMENTS.M_EM_KEY_IS_LIST', 'SOCI.G5.NATURA.ELEMENTS_OF_A_MAP.MAP_ELEMENTS', 'Thinks the key is a list of the places on the map rather than what each symbol means.', '{"question":"What does the key of a map show?","wrong_answer":"The names of all the towns","correct_answer":"What each symbol on the map stands for"}'::jsonb, 'Keys in many textbooks list items beside the symbols, and the child reads only the words.', 'Offer "The names of all the towns" next to the right answer and ask the question again in a new context.', 'Cover the words in a key and ask what each little drawing means on the map.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G5.NATURA.ELEMENTS_OF_A_MAP.MAP_READING.M_EM_SCALE_BIGGER_NUMBER', 'SOCI.G5.NATURA.ELEMENTS_OF_A_MAP.MAP_READING', 'Thinks a scale of 1 cm to 10 km shows a bigger place than 1 cm to 1 km because the number is bigger, and reads distances backwards.', '{"question":"On a map with the scale 1 cm to 5 km, two towns are 3 cm apart. How far apart are they on the ground?","wrong_answer":"3 km","correct_answer":"15 km"}'::jsonb, 'The child has not seen that each centimetre stands for 5 kilometres.', 'Offer "3 km" next to the right answer and ask the question again in a new context.', 'Walk it: mark 3 steps on the floor and say "each step is 5 km": count 5, 10, 15.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G5.NATURA.ELEMENTS_OF_A_MAP.MAP_READING.M_EM_SYMBOL_ANY_COLOUR', 'SOCI.G5.NATURA.ELEMENTS_OF_A_MAP.MAP_READING', 'Thinks blue on a map can mean anything, so reads a blue line as a road.', '{"question":"A map key shows a blue line for a river and a red line for a road. What is the blue line across the plain?","wrong_answer":"A road","correct_answer":"A river"}'::jsonb, 'The child picks the most common thing (a road) instead of checking the key.', 'Offer "A road" next to the right answer and ask the question again in a new context.', 'Point at the key every time before naming a line.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G5.NATURA.LOCATION_POSITION_AND_SI.NEIGHBOURS.M_LP_NEAR_NOT_BORDER', 'SOCI.G5.NATURA.LOCATION_POSITION_AND_SI.NEIGHBOURS', 'Names countries that are near Kenya but share no border (Rwanda, Burundi, Zambia, DR Congo).', '{"question":"Which country shares a border with Kenya?","wrong_answer":"Rwanda","correct_answer":"Uganda"}'::jsonb, 'The child counts East Africa as one group and does not check borders.', 'Offer "Rwanda" next to the right answer and ask the question again in a new context.', 'Trace the border on a described map: which countries touch Kenya at a line? Rwanda lies behind Uganda and Tanzania.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G5.NATURA.LOCATION_POSITION_AND_SI.NEIGHBOURS.M_LP_OCEAN_AS_COUNTRY', 'SOCI.G5.NATURA.LOCATION_POSITION_AND_SI.NEIGHBOURS', 'Counts the Indian Ocean as one of Kenya''s neighbouring countries, or forgets that it is water.', '{"question":"Which of these is a country that borders Kenya?","wrong_answer":"The Indian Ocean","correct_answer":"Somalia"}'::jsonb, 'The child lists everything that touches Kenya on the map.', 'Offer "The Indian Ocean" next to the right answer and ask the question again in a new context.', 'Ask: can a person have a passport from the ocean? Sort touching things into countries and water.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G5.NATURA.LOCATION_POSITION_AND_SI.NEIGHBOUR_DIRECTIONS.M_LP_EAST_WEST_SWAP', 'SOCI.G5.NATURA.LOCATION_POSITION_AND_SI.NEIGHBOUR_DIRECTIONS', 'Swaps east and west when placing Uganda and Somalia.', '{"question":"In which direction from Kenya does Uganda lie?","wrong_answer":"East","correct_answer":"West"}'::jsonb, 'The child remembers that Uganda and Somalia are on the sides but not which side.', 'Offer "East" next to the right answer and ask the question again in a new context.', 'Use the sea: the Indian Ocean is on the east side, so Somalia is east and Uganda is the other side.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G5.NATURA.LOCATION_POSITION_AND_SI.NEIGHBOUR_DIRECTIONS.M_LP_NORTH_SOUTH_SWAP', 'SOCI.G5.NATURA.LOCATION_POSITION_AND_SI.NEIGHBOUR_DIRECTIONS', 'Swaps north and south when placing Ethiopia and Tanzania.', '{"question":"Which country lies to the south of Kenya?","wrong_answer":"Ethiopia","correct_answer":"Tanzania"}'::jsonb, 'The child links the "top" country to the south or confuses the order.', 'Offer "Ethiopia" next to the right answer and ask the question again in a new context.', 'Use Mount Kilimanjaro: it looks over Amboseli, in the south, from Tanzania. Ethiopia is up toward the Horn of Africa.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G5.NATURA.LOCATION_POSITION_AND_SI.NEIGHBOURS.M_LP_EAC_ALL_NEIGHBOURS', 'SOCI.G5.NATURA.LOCATION_POSITION_AND_SI.NEIGHBOURS', 'Thinks every East African Community member (Rwanda, Burundi) shares a border with Kenya.', '{"question":"Rwanda is in the East African Community. Does it share a border with Kenya?","wrong_answer":"Yes, all EAC countries border Kenya","correct_answer":"No, Rwanda does not touch Kenya"}'::jsonb, 'The child links "East African" with "next to Kenya".', 'Offer "Yes, all EAC countries border Kenya" next to the right answer and ask the question again in a new context.', 'On the outline map, trace Kenya''s border and check whether it touches Rwanda.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G5.NATURA.LOCATION_POSITION_AND_SI.NEIGHBOURS.M_LP_ERITREA', 'SOCI.G5.NATURA.LOCATION_POSITION_AND_SI.NEIGHBOURS', 'Names Sudan or Eritrea as a neighbour because they are near Ethiopia and South Sudan.', '{"question":"Which of these shares a border with Kenya: Eritrea, Ethiopia, Sudan?","wrong_answer":"Sudan","correct_answer":"Ethiopia"}'::jsonb, 'The child remembers a country name from the north and picks one that sounds close.', 'Offer "Sudan" next to the right answer and ask the question again in a new context.', 'Point at Sudan on the map: South Sudan lies between it and Kenya.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G5.NATURA.LOCATION_POSITION_AND_SI.NEIGHBOUR_DIRECTIONS.M_LP_DIRECTION_FROM_WHO', 'SOCI.G5.NATURA.LOCATION_POSITION_AND_SI.NEIGHBOUR_DIRECTIONS', 'Gives the direction of Kenya from the neighbour when asked for the neighbour from Kenya.', '{"question":"In which direction is Uganda from Kenya?","wrong_answer":"East","correct_answer":"West"}'::jsonb, 'The child mixes up the starting point of the question.', 'Offer "East" next to the right answer and ask the question again in a new context.', 'Put a finger on Kenya first, then move it to Uganda and name the way it moved.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G5.NATURA.LOCATION_POSITION_AND_SI.NEIGHBOUR_DIRECTIONS.M_LP_OCEAN_WEST', 'SOCI.G5.NATURA.LOCATION_POSITION_AND_SI.NEIGHBOUR_DIRECTIONS', 'Places the Indian Ocean on Kenya''s west because it is the largest water body the child knows, next to Lake Victoria.', '{"question":"On which side of Kenya is the Indian Ocean?","wrong_answer":"West","correct_answer":"South-east"}'::jsonb, 'The child mixes the big lake in the west with the ocean.', 'Offer "West" next to the right answer and ask the question again in a new context.', 'Trace the coast with a finger from Lamu to Vanga and name the direction.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G5.NATURA.MAIN_PHYSICAL_FEATURES_I.FEATURE_NAMES.M_PF_KILIMANJARO', 'SOCI.G5.NATURA.MAIN_PHYSICAL_FEATURES_I.FEATURE_NAMES', 'Thinks Mount Kilimanjaro is in Kenya, or is Kenya''s highest mountain.', '{"question":"What is the highest mountain in Kenya?","wrong_answer":"Mount Kilimanjaro","correct_answer":"Mount Kenya"}'::jsonb, 'Kilimanjaro is seen from Amboseli in Kenya and is famous, so the child places it in Kenya.', 'Offer "Mount Kilimanjaro" next to the right answer and ask the question again in a new context.', 'Show that Kilimanjaro stands on the Tanzanian side. Ask which mountain gave Kenya its name.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G5.NATURA.MAIN_PHYSICAL_FEATURES_I.FEATURE_NAMES.M_PF_TYPE_MIX', 'SOCI.G5.NATURA.MAIN_PHYSICAL_FEATURES_I.FEATURE_NAMES', 'Mixes up the kind of feature (calls a lake a river or a mountain a plateau).', '{"question":"What kind of feature is Lake Turkana?","wrong_answer":"A river","correct_answer":"A lake"}'::jsonb, 'The child knows the name but not the kind of water body.', 'Offer "A river" next to the right answer and ask the question again in a new context.', 'Use the word in the name: lake or mount. Ask whether the water flows or stands.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G5.NATURA.MAIN_PHYSICAL_FEATURES_I.FEATURE_WHERE.M_PF_REGION_MIX', 'SOCI.G5.NATURA.MAIN_PHYSICAL_FEATURES_I.FEATURE_WHERE', 'Places a feature in the wrong part of Kenya (Lake Turkana in the south, Lake Victoria in the east).', '{"question":"In which part of Kenya is Lake Victoria?","wrong_answer":"The east","correct_answer":"The west"}'::jsonb, 'The child remembers the feature but not its side of the country.', 'Offer "The east" next to the right answer and ask the question again in a new context.', 'Link the feature to a neighbour: Lake Victoria is shared with Uganda and Tanzania, so it is on the west.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G5.NATURA.MAIN_PHYSICAL_FEATURES_I.FEATURE_WHERE.M_PF_RIFT_DIRECTION', 'SOCI.G5.NATURA.MAIN_PHYSICAL_FEATURES_I.FEATURE_WHERE', 'Thinks the Great Rift Valley runs east to west, or along the coast.', '{"question":"In which direction does the Great Rift Valley run through Kenya?","wrong_answer":"East to west","correct_answer":"North to south"}'::jsonb, 'The child has not seen a map of the valley and imagines a line across the country.', 'Offer "East to west" next to the right answer and ask the question again in a new context.', 'Describe the Rift lakes in order: Turkana in the north, then Baringo, Nakuru, Naivasha, Magadi toward the south.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G5.NATURA.MAIN_PHYSICAL_FEATURES_I.FEATURE_NAMES.M_PF_LAKE_VICTORIA_ALL_KENYA', 'SOCI.G5.NATURA.MAIN_PHYSICAL_FEATURES_I.FEATURE_NAMES', 'Thinks Lake Victoria lies wholly in Kenya.', '{"question":"Which countries share Lake Victoria?","wrong_answer":"Only Kenya","correct_answer":"Kenya, Uganda and Tanzania"}'::jsonb, 'The child knows the lake from Kisumu and the Kenyan shore only.', 'Offer "Only Kenya" next to the right answer and ask the question again in a new context.', 'On the map, shade the parts of the lake in each country: Kenya has the smallest part.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G5.NATURA.MAIN_PHYSICAL_FEATURES_I.FEATURE_NAMES.M_PF_RIVER_TANA_ATHI', 'SOCI.G5.NATURA.MAIN_PHYSICAL_FEATURES_I.FEATURE_NAMES', 'Thinks the Athi is Kenya''s longest river, or that the Tana flows into Lake Victoria.', '{"question":"Into which water body does the Tana River flow?","wrong_answer":"Lake Victoria","correct_answer":"The Indian Ocean"}'::jsonb, 'The child pictures all rivers flowing to the biggest lake.', 'Offer "Lake Victoria" next to the right answer and ask the question again in a new context.', 'Trace the Tana on the map from the highlands down to the coast.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G5.NATURA.MAIN_PHYSICAL_FEATURES_I.FEATURE_WHERE.M_PF_ELGON_CENTRAL', 'SOCI.G5.NATURA.MAIN_PHYSICAL_FEATURES_I.FEATURE_WHERE', 'Places Mount Elgon in central Kenya next to Mount Kenya.', '{"question":"Where is Mount Elgon?","wrong_answer":"In central Kenya near Mount Kenya","correct_answer":"On the border with Uganda, in the west"}'::jsonb, 'Both are mountains with similar names in lessons.', 'Offer "In central Kenya near Mount Kenya" next to the right answer and ask the question again in a new context.', 'Put both on the map: one in the middle, one on the western border.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G5.NATURA.MAIN_PHYSICAL_FEATURES_I.FEATURE_WHERE.M_PF_COAST_NORTH', 'SOCI.G5.NATURA.MAIN_PHYSICAL_FEATURES_I.FEATURE_WHERE', 'Thinks Kenya''s coast is in the north.', '{"question":"In which part of Kenya is the coast?","wrong_answer":"The north","correct_answer":"The south-east"}'::jsonb, 'The child places the sea at the top of the map like a picture.', 'Offer "The north" next to the right answer and ask the question again in a new context.', 'Trace the coast on the map and name the direction from Nairobi.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G5.NATURA.WEATHER_AND_CLIMATE.WEATHER_ELEMENTS.M_WC_WEATHER_CLIMATE', 'SOCI.G5.NATURA.WEATHER_AND_CLIMATE.WEATHER_ELEMENTS', 'Treats weather and climate as the same thing (thinks climate is today''s conditions).', '{"question":"Which statement is about climate and not weather?","wrong_answer":"It rained heavily this morning.","correct_answer":"Mombasa is hot and humid for most of the year."}'::jsonb, 'Both words are used for the air, and the child does not link climate to a long time.', 'Offer "It rained heavily this morning." next to the right answer and ask the question again in a new context.', 'Ask "how long did we watch?" One day is weather. Many years is climate.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G5.NATURA.WEATHER_AND_CLIMATE.WEATHER_ELEMENTS.M_WC_INSTRUMENT_MIX', 'SOCI.G5.NATURA.WEATHER_AND_CLIMATE.WEATHER_ELEMENTS', 'Matches a weather instrument to the wrong element (rain gauge for temperature).', '{"question":"Which instrument measures the amount of rain?","wrong_answer":"A thermometer","correct_answer":"A rain gauge"}'::jsonb, 'The child knows the names but not the jobs.', 'Offer "A thermometer" next to the right answer and ask the question again in a new context.', 'Match each instrument to a unit: degrees, millimetres, direction.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G5.NATURA.WEATHER_AND_CLIMATE.CLIMATE_REGION_PLACES.M_WC_REGION_MIX', 'SOCI.G5.NATURA.WEATHER_AND_CLIMATE.CLIMATE_REGION_PLACES', 'Swaps the hot dry north with the cool highlands when naming where a region lies.', '{"question":"Which part of Kenya has an arid climate, with very little rain?","wrong_answer":"The area around Mount Kenya","correct_answer":"Turkana in the north-west"}'::jsonb, 'The child links "high" and "far" together, or links the big mountain with dry land.', 'Offer "The area around Mount Kenya" next to the right answer and ask the question again in a new context.', 'Match three towns to rain: Nyeri (much rain), Mombasa (humid), Lodwar (very little).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G5.NATURA.WEATHER_AND_CLIMATE.CLIMATE_REGION_PLACES.M_WC_COAST_DRY', 'SOCI.G5.NATURA.WEATHER_AND_CLIMATE.CLIMATE_REGION_PLACES', 'Thinks the coast is hot and dry like the north.', '{"question":"Which description fits Mombasa on the coast?","wrong_answer":"Hot and dry with very little rain","correct_answer":"Hot and humid with plenty of rain"}'::jsonb, 'The child groups all hot places together.', 'Offer "Hot and dry with very little rain" next to the right answer and ask the question again in a new context.', 'Hot has two kinds: dry (Lodwar) and humid (Mombasa). Ask about the sea air.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G5.NATURA.WEATHER_AND_CLIMATE.CLIMATE_REGION_TRAITS.M_WC_EQUATOR_HOT', 'SOCI.G5.NATURA.WEATHER_AND_CLIMATE.CLIMATE_REGION_TRAITS', 'Thinks everywhere near the equator is hot, so Mount Kenya has no cold.', '{"question":"Mount Kenya is on the equator. Why is it cold at the top?","wrong_answer":"It is not cold there.","correct_answer":"The air is cooler as you go higher up."}'::jsonb, 'The child connects the equator with heat and has not met height.', 'Offer "It is not cold there." next to the right answer and ask the question again in a new context.', 'Ask: is it colder at the top of a high hill than at its foot? Then link to the mountain.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G5.NATURA.WEATHER_AND_CLIMATE.CLIMATE_REGION_TRAITS.M_WC_HUMID_DRY', 'SOCI.G5.NATURA.WEATHER_AND_CLIMATE.CLIMATE_REGION_TRAITS', 'Thinks humid means dry, or that humid means cold.', '{"question":"What does it mean when the coast is humid?","wrong_answer":"The air is very dry.","correct_answer":"The air has a lot of water vapour in it."}'::jsonb, 'The child has heard humid together with hot and guesses.', 'Offer "The air is very dry." next to the right answer and ask the question again in a new context.', 'Use clothes that do not dry on a humid day.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G5.NATURA.WEATHER_AND_CLIMATE.WEATHER_ELEMENTS.M_WC_WIND_VANE_SPEED', 'SOCI.G5.NATURA.WEATHER_AND_CLIMATE.WEATHER_ELEMENTS', 'Thinks a wind vane measures how fast the wind blows.', '{"question":"What does a wind vane show?","wrong_answer":"How fast the wind is blowing","correct_answer":"The direction the wind is blowing from"}'::jsonb, 'Both the vane and the anemometer are about wind, and the child knows one word.', 'Offer "How fast the wind is blowing" next to the right answer and ask the question again in a new context.', 'Make a card vane and watch it turn to face the wind; then spin a cup anemometer.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G5.NATURA.WEATHER_AND_CLIMATE.WEATHER_ELEMENTS.M_WC_CLOUD_RAIN_ALWAYS', 'SOCI.G5.NATURA.WEATHER_AND_CLIMATE.WEATHER_ELEMENTS', 'Thinks every cloudy day is a rainy day.', '{"question":"The sky is full of clouds but no rain falls. What is the weather?","wrong_answer":"Rainy","correct_answer":"Cloudy"}'::jsonb, 'The child links clouds with rain so strongly that they treat them as one element.', 'Offer "Rainy" next to the right answer and ask the question again in a new context.', 'Record cloud cover and rainfall in separate columns for a week.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G5.NATURA.WEATHER_AND_CLIMATE.CLIMATE_REGION_PLACES.M_WC_NAIROBI_COAST', 'SOCI.G5.NATURA.WEATHER_AND_CLIMATE.CLIMATE_REGION_PLACES', 'Puts Nairobi in the hot humid coastal region.', '{"question":"Which climate region is Nairobi closest to?","wrong_answer":"The hot humid coast","correct_answer":"The cool highlands"}'::jsonb, 'Nairobi is the capital and the child links it with the big port city.', 'Offer "The hot humid coast" next to the right answer and ask the question again in a new context.', 'Compare Nairobi''s cool mornings with Mombasa''s warm nights on a temperature chart.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G5.NATURA.WEATHER_AND_CLIMATE.CLIMATE_REGION_PLACES.M_WC_LAKE_ARID', 'SOCI.G5.NATURA.WEATHER_AND_CLIMATE.CLIMATE_REGION_PLACES', 'Places the Lake Victoria basin in the dry arid region.', '{"question":"Which climate region is around Lake Victoria?","wrong_answer":"Hot and dry arid","correct_answer":"Warm with rain for much of the year"}'::jsonb, 'The child knows the west is hot and thinks hot means dry.', 'Offer "Hot and dry arid" next to the right answer and ask the question again in a new context.', 'Show the rainfall bars for Kisumu and Lodwar side by side.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G5.NATURA.WEATHER_AND_CLIMATE.CLIMATE_REGION_TRAITS.M_WC_HIGHLAND_HOT', 'SOCI.G5.NATURA.WEATHER_AND_CLIMATE.CLIMATE_REGION_TRAITS', 'Thinks the highlands are the hottest region because they are closest to the sun.', '{"question":"Why is Nyeri cooler than Mombasa?","wrong_answer":"Nyeri is far from the sun","correct_answer":"Nyeri is high above the sea, and high places are cooler"}'::jsonb, 'The child reasons that higher means closer to the sun and so hotter.', 'Offer "Nyeri is far from the sun" next to the right answer and ask the question again in a new context.', 'Show photos of snow on Mount Kenya: the highest place is the coldest.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G5.NATURA.WEATHER_AND_CLIMATE.CLIMATE_REGION_TRAITS.M_WC_ARID_NO_PEOPLE', 'SOCI.G5.NATURA.WEATHER_AND_CLIMATE.CLIMATE_REGION_TRAITS', 'Thinks nobody can live in the arid region.', '{"question":"How do many people in the arid north earn a living?","wrong_answer":"Nobody lives there","correct_answer":"By keeping camels, goats and cattle and moving to find pasture"}'::jsonb, 'The child hears "desert" and pictures empty sand.', 'Offer "Nobody lives there" next to the right answer and ask the question again in a new context.', 'Show a photo of a pastoralist family with camels in Marsabit.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G5.NATURA.THE_BUILT_ENVIRONMENTS.HISTORIC_SITES.M_BE_NATURAL_AS_BUILT', 'SOCI.G5.NATURA.THE_BUILT_ENVIRONMENTS.HISTORIC_SITES', 'Counts a natural feature (Mount Kenya, a lake) as a historic built environment.', '{"question":"Which of these is a historic built environment?","wrong_answer":"Mount Kenya","correct_answer":"Fort Jesus"}'::jsonb, 'The child links "famous place" with "historic site".', 'Offer "Mount Kenya" next to the right answer and ask the question again in a new context.', 'Sort cards: made by people, or made by nature?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G5.NATURA.THE_BUILT_ENVIRONMENTS.HISTORIC_SITES.M_BE_PLACE_MIX', 'SOCI.G5.NATURA.THE_BUILT_ENVIRONMENTS.HISTORIC_SITES', 'Places a site in the wrong town (Fort Jesus in Lamu, Gedi in Nairobi).', '{"question":"In which town is Fort Jesus?","wrong_answer":"Lamu","correct_answer":"Mombasa"}'::jsonb, 'Lamu and Mombasa are both old coastal towns.', 'Offer "Lamu" next to the right answer and ask the question again in a new context.', 'Tell the stories: the Portuguese built Fort Jesus at Mombasa; Lamu Old Town is a town of coral stone houses.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G5.NATURA.THE_BUILT_ENVIRONMENTS.CONSERVATION.M_BE_KEEP_OUT', 'SOCI.G5.NATURA.THE_BUILT_ENVIRONMENTS.CONSERVATION', 'Thinks conserving a site means closing it to everyone or pulling it down to build new.', '{"question":"What is the best way to conserve an old fort?","wrong_answer":"Pull it down and build a new one","correct_answer":"Repair it carefully and let visitors see it with rules"}'::jsonb, 'The child confuses old with useless or keeping safe with locking away.', 'Offer "Pull it down and build a new one" next to the right answer and ask the question again in a new context.', 'Ask what a grandparent would lose if a home photo album were thrown away.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G5.NATURA.THE_BUILT_ENVIRONMENTS.CONSERVATION.M_BE_TOUCH_TAKE', 'SOCI.G5.NATURA.THE_BUILT_ENVIRONMENTS.CONSERVATION', 'Thinks that taking a small stone or writing a name on an old wall does no harm.', '{"question":"A visitor wants a small stone from an old wall. What should you say?","wrong_answer":"It is only a small stone, so it is fine.","correct_answer":"No, if everyone took one the wall would be gone."}'::jsonb, 'The child thinks one person cannot cause damage.', 'Offer "It is only a small stone, so it is fine." next to the right answer and ask the question again in a new context.', 'Ask what happens when 100 visitors each take one stone.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G5.NATURA.THE_BUILT_ENVIRONMENTS.HISTORIC_SITES.M_BE_FORT_KENYAN_BUILT', 'SOCI.G5.NATURA.THE_BUILT_ENVIRONMENTS.HISTORIC_SITES', 'Thinks Fort Jesus was built by the British.', '{"question":"Who built Fort Jesus?","wrong_answer":"The British","correct_answer":"The Portuguese"}'::jsonb, 'The child knows the British ruled Kenya and puts every old building on them.', 'Offer "The British" next to the right answer and ask the question again in a new context.', 'Put the Portuguese arrival (1500s) and the British (1890s) on a timeline with Fort Jesus.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G5.NATURA.THE_BUILT_ENVIRONMENTS.HISTORIC_SITES.M_BE_THIMLICH_COAST', 'SOCI.G5.NATURA.THE_BUILT_ENVIRONMENTS.HISTORIC_SITES', 'Thinks every stone ruin in Kenya is at the coast, so places Thimlich Ohinga there.', '{"question":"Where is Thimlich Ohinga?","wrong_answer":"At the coast","correct_answer":"In Migori, near Lake Victoria"}'::jsonb, 'The best-known ruins are at the coast.', 'Offer "At the coast" next to the right answer and ask the question again in a new context.', 'Mark both Gedi and Thimlich Ohinga on the map.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G5.NATURA.THE_BUILT_ENVIRONMENTS.CONSERVATION.M_BE_NEW_PAINT', 'SOCI.G5.NATURA.THE_BUILT_ENVIRONMENTS.CONSERVATION', 'Thinks painting an old fort in bright new colours is conserving it.', '{"question":"Is painting Fort Jesus bright blue a good way to conserve it?","wrong_answer":"Yes, it makes it look new","correct_answer":"No, conserving means keeping it as it was with careful repairs"}'::jsonb, 'The child thinks caring means making things look new.', 'Offer "Yes, it makes it look new" next to the right answer and ask the question again in a new context.', 'Show a photo of a careful repair that matches the old stone.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G5.NATURA.THE_BUILT_ENVIRONMENTS.CONSERVATION.M_BE_GOVT_ONLY', 'SOCI.G5.NATURA.THE_BUILT_ENVIRONMENTS.CONSERVATION', 'Thinks only the government can conserve historic sites.', '{"question":"Who can help conserve historic sites?","wrong_answer":"Only the government","correct_answer":"Everyone: visitors, learners, the community and the National Museums of Kenya"}'::jsonb, 'The child hears the National Museums named and thinks it is their job alone.', 'Offer "Only the government" next to the right answer and ask the question again in a new context.', 'List what a learner can do: not litter, tell others, report damage.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G5.PEOPLE.LANGUAGE_GROUPS_IN_KENYA.GROUP_SORT.M_LG_NILOTE_AS_BANTU', 'SOCI.G5.PEOPLE.LANGUAGE_GROUPS_IN_KENYA.GROUP_SORT', 'Puts the Luo, Kalenjin or Maasai in the Bantu group.', '{"question":"To which language group do the Luo belong?","wrong_answer":"Bantu","correct_answer":"Nilotic"}'::jsonb, 'The child knows the largest group is Bantu and sorts most communities into it.', 'Offer "Bantu" next to the right answer and ask the question again in a new context.', 'Start with the Bantu list (Kikuyu, Luhya, Kamba), then name the Nilotes by their lake and plain homes.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G5.PEOPLE.LANGUAGE_GROUPS_IN_KENYA.GROUP_SORT.M_LG_CUSHITE_AS_NILOTE', 'SOCI.G5.PEOPLE.LANGUAGE_GROUPS_IN_KENYA.GROUP_SORT', 'Puts the Somali, Borana or Rendille among the Nilotes (or among the Bantu).', '{"question":"To which language group do the Somali belong?","wrong_answer":"Nilotic","correct_answer":"Cushitic"}'::jsonb, 'Many northern communities are herders, and the child groups herders together.', 'Offer "Nilotic" next to the right answer and ask the question again in a new context.', 'Group by language family, not by way of life: Maasai are herders and Nilotes, Somali are herders and Cushites.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G5.PEOPLE.LANGUAGE_GROUPS_IN_KENYA.INTERDEPENDENCE.M_LG_SELF_SUFFICIENT', 'SOCI.G5.PEOPLE.LANGUAGE_GROUPS_IN_KENYA.INTERDEPENDENCE', 'Thinks each community can supply all it needs and has no need of others.', '{"question":"A fishing community has plenty of fish but no maize. What can it do?","wrong_answer":"Nothing, it must fish more","correct_answer":"Trade fish for maize with a farming community"}'::jsonb, 'The child thinks of a community as separate from neighbours.', 'Offer "Nothing, it must fish more" next to the right answer and ask the question again in a new context.', 'Ask each group what it has and what it lacks, then join the groups.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G5.PEOPLE.LANGUAGE_GROUPS_IN_KENYA.INTERDEPENDENCE.M_LG_RIVALRY', 'SOCI.G5.PEOPLE.LANGUAGE_GROUPS_IN_KENYA.INTERDEPENDENCE', 'Thinks depending on each other means competing or quarrelling.', '{"question":"What does interdependence between communities mean?","wrong_answer":"They compete to be the strongest","correct_answer":"They help each other by sharing goods and skills"}'::jsonb, 'The child hears the word as a conflict.', 'Offer "They compete to be the strongest" next to the right answer and ask the question again in a new context.', 'Use a market scene where both sides gain.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G5.PEOPLE.LANGUAGE_GROUPS_IN_KENYA.GROUP_SORT.M_LG_REGION_GROUP', 'SOCI.G5.PEOPLE.LANGUAGE_GROUPS_IN_KENYA.GROUP_SORT', 'Groups communities by where they live now rather than by language family.', '{"question":"The Maasai live in the south and the Turkana in the north. Are they in the same language group?","wrong_answer":"No, they live far apart","correct_answer":"Yes, both are Nilotes"}'::jsonb, 'The child sorts by the map, not by the language.', 'Offer "No, they live far apart" next to the right answer and ask the question again in a new context.', 'Show a few shared words among Nilotic languages and their spread on the map.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G5.PEOPLE.LANGUAGE_GROUPS_IN_KENYA.GROUP_SORT.M_LG_GROUP_IS_TRIBE', 'SOCI.G5.PEOPLE.LANGUAGE_GROUPS_IN_KENYA.GROUP_SORT', 'Thinks a language group is one tribe.', '{"question":"Is \"Bantu\" the name of one community?","wrong_answer":"Yes, it is one tribe","correct_answer":"No, it is a group of many communities with related languages"}'::jsonb, 'The child hears "the Bantu" like "the Kamba".', 'Offer "Yes, it is one tribe" next to the right answer and ask the question again in a new context.', 'List six Bantu communities under the word Bantu.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G5.PEOPLE.LANGUAGE_GROUPS_IN_KENYA.INTERDEPENDENCE.M_LG_TRADE_ONLY', 'SOCI.G5.PEOPLE.LANGUAGE_GROUPS_IN_KENYA.INTERDEPENDENCE', 'Thinks communities depend on each other only for trade.', '{"question":"Give a way communities depend on each other other than trade.","wrong_answer":"There is no other way","correct_answer":"Intermarriage, sharing ideas and skills, and working together"}'::jsonb, 'Barter trade is the first example taught.', 'Offer "There is no other way" next to the right answer and ask the question again in a new context.', 'List what neighbouring communities share: language words, songs, marriages, farming ideas.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G5.PEOPLE.LANGUAGE_GROUPS_IN_KENYA.INTERDEPENDENCE.M_LG_ONE_LANGUAGE_NEEDED', 'SOCI.G5.PEOPLE.LANGUAGE_GROUPS_IN_KENYA.INTERDEPENDENCE', 'Thinks communities can only work together if they speak the same mother tongue.', '{"question":"How do people from different language groups talk at a market in Kenya?","wrong_answer":"They cannot","correct_answer":"They use Kiswahili or English"}'::jsonb, 'The child knows only their own language links people.', 'Offer "They cannot" next to the right answer and ask the question again in a new context.', 'Act a market with buyers from different groups using Kiswahili.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G5.PEOPLE.POPULATION_DISTRIBUTION_.DENSITY_AREAS.M_PD_DESERT_DENSE', 'SOCI.G5.PEOPLE.POPULATION_DISTRIBUTION_.DENSITY_AREAS', 'Thinks the dry north is crowded because it is large, or that people prefer dry land.', '{"question":"Which area has a low population density?","wrong_answer":"The Mount Kenya highlands","correct_answer":"The dry area around Marsabit"}'::jsonb, 'The child links size of an area with the number of people.', 'Offer "The Mount Kenya highlands" next to the right answer and ask the question again in a new context.', 'Ask what people need to farm and live: water and good soil. Then compare the two places.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G5.PEOPLE.POPULATION_DISTRIBUTION_.DENSITY_AREAS.M_PD_SIZE_DENSITY', 'SOCI.G5.PEOPLE.POPULATION_DISTRIBUTION_.DENSITY_AREAS', 'Thinks a county with more people in total has the higher density, whatever its size.', '{"question":"Area A has 600 people on 3 square kilometres. Area B has 600 people on 6 square kilometres. Which is more crowded?","wrong_answer":"Both are the same","correct_answer":"Area A"}'::jsonb, 'The child compares the number of people only.', 'Offer "Both are the same" next to the right answer and ask the question again in a new context.', 'Draw both areas on squared paper and place the 600 people in each.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G5.PEOPLE.POPULATION_DISTRIBUTION_.DENSITY_EFFECTS.M_PD_DENSE_ALL_GOOD', 'SOCI.G5.PEOPLE.POPULATION_DISTRIBUTION_.DENSITY_EFFECTS', 'Thinks a crowded area has only benefits (or no problems).', '{"question":"What is a problem of a very high population density?","wrong_answer":"There are no problems at all","correct_answer":"Pressure on land, water and housing"}'::jsonb, 'The child links many people with many opportunities only.', 'Offer "There are no problems at all" next to the right answer and ask the question again in a new context.', 'List both: easy markets and many schools, but small plots and crowded roads.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G5.PEOPLE.POPULATION_DISTRIBUTION_.DENSITY_EFFECTS.M_PD_SPARSE_NO_PROBLEM', 'SOCI.G5.PEOPLE.POPULATION_DISTRIBUTION_.DENSITY_EFFECTS', 'Thinks a thinly settled area has no problems.', '{"question":"What is a problem of a very low population density?","wrong_answer":"Crowded schools and roads","correct_answer":"Services such as schools and clinics are far apart"}'::jsonb, 'The child thinks empty means easy.', 'Offer "Crowded schools and roads" next to the right answer and ask the question again in a new context.', 'Ask how far a child walks to the nearest school in a thinly settled area.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G5.PEOPLE.POPULATION_DISTRIBUTION_.DENSITY_AREAS.M_PD_NAIROBI_ONLY', 'SOCI.G5.PEOPLE.POPULATION_DISTRIBUTION_.DENSITY_AREAS', 'Thinks Nairobi is the only densely populated place in Kenya.', '{"question":"Which of these areas is also densely populated: the Lake Victoria basin or the Chalbi Desert?","wrong_answer":"Neither; only Nairobi is dense","correct_answer":"The Lake Victoria basin"}'::jsonb, 'The child thinks only cities can be crowded.', 'Offer "Neither; only Nairobi is dense" next to the right answer and ask the question again in a new context.', 'Show a density map with several dark areas.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G5.PEOPLE.POPULATION_DISTRIBUTION_.DENSITY_AREAS.M_PD_DENSITY_IS_TOTAL', 'SOCI.G5.PEOPLE.POPULATION_DISTRIBUTION_.DENSITY_AREAS', 'Works out density by adding people instead of dividing people by area.', '{"question":"An area of 10 square kilometres has 500 people. What is its density?","wrong_answer":"510","correct_answer":"50 people per square kilometre"}'::jsonb, 'The child adds the two numbers given.', 'Offer "510" next to the right answer and ask the question again in a new context.', 'Spread 500 beans over 10 squares and count how many sit on each square.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G5.PEOPLE.POPULATION_DISTRIBUTION_.DENSITY_EFFECTS.M_PD_DENSE_FARMS_BIG', 'SOCI.G5.PEOPLE.POPULATION_DISTRIBUTION_.DENSITY_EFFECTS', 'Thinks farms are bigger where many people live.', '{"question":"Where are farms usually smaller: where density is high or low?","wrong_answer":"Where density is low","correct_answer":"Where density is high"}'::jsonb, 'The child links many people with much farming.', 'Offer "Where density is low" next to the right answer and ask the question again in a new context.', 'Share a field among four families, then among twelve.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G5.PEOPLE.POPULATION_DISTRIBUTION_.DENSITY_EFFECTS.M_PD_SPARSE_SERVICES_EASY', 'SOCI.G5.PEOPLE.POPULATION_DISTRIBUTION_.DENSITY_EFFECTS', 'Thinks services such as schools are easy to reach where few people live.', '{"question":"Why might a child in a sparsely populated area walk far to school?","wrong_answer":"Schools are everywhere","correct_answer":"Few people means few schools, spread far apart"}'::jsonb, 'The child assumes every place has a school nearby like their own.', 'Offer "Schools are everywhere" next to the right answer and ask the question again in a new context.', 'Plot schools on the bean map: few beans, few schools.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G5.PEOPLE.AFRICAN_TRADITIONAL_EDUC.ATE_METHODS.M_TE_NO_SCHOOL', 'SOCI.G5.PEOPLE.AFRICAN_TRADITIONAL_EDUC.ATE_METHODS', 'Thinks children had no education before schools and teachers came.', '{"question":"How did children learn before schools with classrooms were built?","wrong_answer":"They did not learn anything","correct_answer":"From elders and parents through stories, work and songs"}'::jsonb, 'The child equates education with a classroom.', 'Offer "They did not learn anything" next to the right answer and ask the question again in a new context.', 'Ask how a child learned to herd or farm, and who taught her.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G5.PEOPLE.AFRICAN_TRADITIONAL_EDUC.ATE_METHODS.M_TE_METHOD_MIX', 'SOCI.G5.PEOPLE.AFRICAN_TRADITIONAL_EDUC.ATE_METHODS', 'Mixes up the methods (calls a proverb "role play", or learning by doing "storytelling").', '{"question":"A girl learns to cook by helping her aunt every day. Which method is this?","wrong_answer":"Storytelling","correct_answer":"Learning by doing"}'::jsonb, 'The child knows the names but does not match them to a scene.', 'Offer "Storytelling" next to the right answer and ask the question again in a new context.', 'Describe three scenes and have the child name each: a story, a song, a task.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G5.PEOPLE.AFRICAN_TRADITIONAL_EDUC.ATE_VALUES.M_TE_ONLY_SKILLS', 'SOCI.G5.PEOPLE.AFRICAN_TRADITIONAL_EDUC.ATE_VALUES', 'Thinks traditional education taught only skills (herding, farming) and no values.', '{"question":"What did traditional education teach besides skills?","wrong_answer":"Nothing else","correct_answer":"Values such as respect, honesty and responsibility"}'::jsonb, 'The child sees work but not the lessons inside the stories and customs.', 'Offer "Nothing else" next to the right answer and ask the question again in a new context.', 'Read a proverb and ask what it teaches about behaviour.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G5.PEOPLE.AFRICAN_TRADITIONAL_EDUC.ATE_VALUES.M_TE_OUTDATED', 'SOCI.G5.PEOPLE.AFRICAN_TRADITIONAL_EDUC.ATE_VALUES', 'Thinks traditional education has no use today.', '{"question":"Why is African traditional education still useful?","wrong_answer":"It is not useful now","correct_answer":"Its values and community lessons still guide behaviour"}'::jsonb, 'The child thinks old things are of no use.', 'Offer "It is not useful now" next to the right answer and ask the question again in a new context.', 'Pick a value the school teaches and find the same one in a proverb.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G5.PEOPLE.AFRICAN_TRADITIONAL_EDUC.ATE_METHODS.M_TE_TEACHER_ONLY', 'SOCI.G5.PEOPLE.AFRICAN_TRADITIONAL_EDUC.ATE_METHODS', 'Thinks only one teacher taught children, like in a school.', '{"question":"Who taught children in African traditional education?","wrong_answer":"One teacher in a classroom","correct_answer":"Parents, grandparents, elders and the whole community"}'::jsonb, 'The child pictures education as a classroom.', 'Offer "One teacher in a classroom" next to the right answer and ask the question again in a new context.', 'Ask learners what they learnt from a grandparent.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G5.PEOPLE.AFRICAN_TRADITIONAL_EDUC.ATE_METHODS.M_TE_RIDDLE_PLAY', 'SOCI.G5.PEOPLE.AFRICAN_TRADITIONAL_EDUC.ATE_METHODS', 'Thinks riddles and stories were only for fun, not for learning.', '{"question":"Why did grandmothers tell stories in the evening?","wrong_answer":"Only to make children laugh","correct_answer":"To teach lessons and values while children enjoyed them"}'::jsonb, 'The child enjoys stories and does not see the lesson.', 'Offer "Only to make children laugh" next to the right answer and ask the question again in a new context.', 'Tell the hare and the hyena and ask what the story teaches.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G5.PEOPLE.AFRICAN_TRADITIONAL_EDUC.ATE_VALUES.M_TE_BOYS_ONLY', 'SOCI.G5.PEOPLE.AFRICAN_TRADITIONAL_EDUC.ATE_VALUES', 'Thinks only boys received traditional education.', '{"question":"Did girls receive traditional education?","wrong_answer":"No, only boys","correct_answer":"Yes, girls learnt from mothers, grandmothers and women elders"}'::jsonb, 'The child has heard more about boys'' initiation and herding.', 'Offer "No, only boys" next to the right answer and ask the question again in a new context.', 'List skills girls learnt: cooking, farming, pottery, caring for the family.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G5.PEOPLE.AFRICAN_TRADITIONAL_EDUC.ATE_VALUES.M_TE_VALUE_MATCH', 'SOCI.G5.PEOPLE.AFRICAN_TRADITIONAL_EDUC.ATE_VALUES', 'Matches a practice to the wrong value (sharing food taught courage).', '{"question":"Children were taught to share food with visitors. Which value did this teach?","wrong_answer":"Courage","correct_answer":"Generosity and sharing"}'::jsonb, 'The child picks any value they remember.', 'Offer "Courage" next to the right answer and ask the question again in a new context.', 'Act the practice and ask what kind of person it makes.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G5.PEOPLE.SCHOOL_ADMINISTRATION.ADMIN_LEADERS.M_SA_DEPUTY_HEAD', 'SOCI.G5.PEOPLE.SCHOOL_ADMINISTRATION.ADMIN_LEADERS', 'Thinks the deputy headteacher is the head of the school.', '{"question":"Who is in charge of the whole school?","wrong_answer":"The deputy headteacher","correct_answer":"The headteacher"}'::jsonb, 'The child confuses the one who acts in the head''s absence with the head.', 'Offer "The deputy headteacher" next to the right answer and ask the question again in a new context.', 'Ask who is in charge on a day when both are present and who helps.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G5.PEOPLE.SCHOOL_ADMINISTRATION.ADMIN_LEADERS.M_SA_DUTY_MIX', 'SOCI.G5.PEOPLE.SCHOOL_ADMINISTRATION.ADMIN_LEADERS', 'Gives a leader the duty of another (class teacher manages the school money, BOM teaches the class).', '{"question":"Who takes the class register each morning?","wrong_answer":"The Board of Management","correct_answer":"The class teacher"}'::jsonb, 'The child knows the names but not who does what.', 'Offer "The Board of Management" next to the right answer and ask the question again in a new context.', 'Match each duty to the person whose desk or room it is done at.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G5.PEOPLE.SCHOOL_ADMINISTRATION.ADMIN_STRUCTURE.M_SA_ORDER_REVERSED', 'SOCI.G5.PEOPLE.SCHOOL_ADMINISTRATION.ADMIN_STRUCTURE', 'Puts the deputy headteacher above the headteacher on a chart.', '{"question":"On a school chart, who is placed directly under the headteacher?","wrong_answer":"The class teachers","correct_answer":"The deputy headteacher"}'::jsonb, 'The child places the nearest staff at the top or mixes the order.', 'Offer "The class teachers" next to the right answer and ask the question again in a new context.', 'Draw the chart from the top down, one level at a time.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G5.PEOPLE.SCHOOL_ADMINISTRATION.ADMIN_STRUCTURE.M_SA_PREFECT_ABOVE', 'SOCI.G5.PEOPLE.SCHOOL_ADMINISTRATION.ADMIN_STRUCTURE', 'Thinks prefects rank above teachers.', '{"question":"Who reports to the class teacher?","wrong_answer":"The headteacher","correct_answer":"The learners and their class prefects"}'::jsonb, 'The child thinks prefects have power over staff.', 'Offer "The headteacher" next to the right answer and ask the question again in a new context.', 'Ask who gives prefects their duties.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G5.PEOPLE.SCHOOL_ADMINISTRATION.ADMIN_LEADERS.M_SA_BOM_TEACHERS', 'SOCI.G5.PEOPLE.SCHOOL_ADMINISTRATION.ADMIN_LEADERS', 'Thinks the Board of Management is made up of the school''s teachers.', '{"question":"Who is on the Board of Management?","wrong_answer":"Only the teachers","correct_answer":"Members such as parents'' and community representatives, with the head teacher as secretary"}'::jsonb, 'The child has only seen teachers running the school.', 'Offer "Only the teachers" next to the right answer and ask the question again in a new context.', 'Show the school''s BOM list (posts only) and count who are not teachers.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G5.PEOPLE.SCHOOL_ADMINISTRATION.ADMIN_LEADERS.M_SA_SUPPORT_NOT_STAFF', 'SOCI.G5.PEOPLE.SCHOOL_ADMINISTRATION.ADMIN_LEADERS', 'Thinks cooks, cleaners and guards are not part of the school.', '{"question":"Are the school cook and the guard part of the school community?","wrong_answer":"No, only teachers are","correct_answer":"Yes, they are support staff who keep the school running"}'::jsonb, 'The child sees teaching as the only school work.', 'Offer "No, only teachers are" next to the right answer and ask the question again in a new context.', 'List what would happen if there were no cook or guard for a week.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G5.PEOPLE.SCHOOL_ADMINISTRATION.ADMIN_STRUCTURE.M_SA_CLASS_TEACHER_TOP', 'SOCI.G5.PEOPLE.SCHOOL_ADMINISTRATION.ADMIN_STRUCTURE', 'Thinks the class teacher is the highest authority because they are the one the child sees most.', '{"question":"Who has more authority in the school: the class teacher or the headteacher?","wrong_answer":"The class teacher","correct_answer":"The headteacher"}'::jsonb, 'Closeness is mistaken for rank.', 'Offer "The class teacher" next to the right answer and ask the question again in a new context.', 'Trace on the chart who the class teacher reports to.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G5.PEOPLE.SCHOOL_ADMINISTRATION.ADMIN_STRUCTURE.M_SA_PARENTS_OUTSIDE', 'SOCI.G5.PEOPLE.SCHOOL_ADMINISTRATION.ADMIN_STRUCTURE', 'Thinks parents have no part in running the school.', '{"question":"How do parents take part in running a school?","wrong_answer":"They do not","correct_answer":"Through the parents'' association and representatives on the Board of Management"}'::jsonb, 'The child sees parents only at the gate.', 'Offer "They do not" next to the right answer and ask the question again in a new context.', 'Show the date of the next parents'' meeting and what it decides.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G5.RESOUR.RESOURCES_IN_KENYA.RESOURCE_TYPES.M_RK_MONEY_ONLY', 'SOCI.G5.RESOUR.RESOURCES_IN_KENYA.RESOURCE_TYPES', 'Thinks resources mean only money.', '{"question":"Which of these is a natural resource of Kenya?","wrong_answer":"Money in a bank","correct_answer":"Water in Lake Victoria"}'::jsonb, 'The child thinks of wealth as cash.', 'Offer "Money in a bank" next to the right answer and ask the question again in a new context.', 'Ask what people used before they had money.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G5.RESOUR.RESOURCES_IN_KENYA.RESOURCE_TYPES.M_RK_BUILT_NATURAL', 'SOCI.G5.RESOUR.RESOURCES_IN_KENYA.RESOURCE_TYPES', 'Counts something people built (a road, a school) as a natural resource.', '{"question":"Which of these is a natural resource?","wrong_answer":"A school building","correct_answer":"A forest"}'::jsonb, 'The child thinks that anything useful is a natural resource.', 'Offer "A school building" next to the right answer and ask the question again in a new context.', 'Sort cards into made by nature or made by people.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G5.RESOUR.RESOURCES_IN_KENYA.PRUDENT_USE.M_RK_CONSERVE_NO_USE', 'SOCI.G5.RESOUR.RESOURCES_IN_KENYA.PRUDENT_USE', 'Thinks conserving a resource means never using it.', '{"question":"What does it mean to use a resource prudently?","wrong_answer":"Never use it","correct_answer":"Use it carefully so it lasts"}'::jsonb, 'The child thinks protection means keeping hands off.', 'Offer "Never use it" next to the right answer and ask the question again in a new context.', 'Compare a family that uses water carefully with one that wastes it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G5.RESOUR.RESOURCES_IN_KENYA.PRUDENT_USE.M_RK_UNLIMITED', 'SOCI.G5.RESOUR.RESOURCES_IN_KENYA.PRUDENT_USE', 'Thinks resources such as forests and fish cannot run out because they grow back.', '{"question":"If people cut all the trees in a forest without planting new ones, what happens?","wrong_answer":"The forest grows back at once","correct_answer":"The forest can disappear"}'::jsonb, 'The child sees "renewable" as "never ends".', 'Offer "The forest grows back at once" next to the right answer and ask the question again in a new context.', 'Compare how long a tree takes to grow with how fast it can be cut.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G5.RESOUR.RESOURCES_IN_KENYA.RESOURCE_TYPES.M_RK_PEOPLE_NOT', 'SOCI.G5.RESOUR.RESOURCES_IN_KENYA.RESOURCE_TYPES', 'Does not count people''s skills as a resource for the country.', '{"question":"Are skilled people a resource for Kenya?","wrong_answer":"No, resources are only things from nature","correct_answer":"Yes, human resources: people''s skills and work"}'::jsonb, 'The lesson stresses natural resources.', 'Offer "No, resources are only things from nature" next to the right answer and ask the question again in a new context.', 'List what a nurse or a fundi gives the country.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G5.RESOUR.RESOURCES_IN_KENYA.RESOURCE_TYPES.M_RK_SUN_NOT', 'SOCI.G5.RESOUR.RESOURCES_IN_KENYA.RESOURCE_TYPES', 'Does not count sunshine or wind as resources because they cannot be held.', '{"question":"Is wind a resource?","wrong_answer":"No, you cannot hold it","correct_answer":"Yes, it can turn windmills to make electricity"}'::jsonb, 'The child thinks a resource must be a thing you can carry.', 'Offer "No, you cannot hold it" next to the right answer and ask the question again in a new context.', 'Show the wind farm at Lake Turkana or a solar panel on a roof.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G5.RESOUR.RESOURCES_IN_KENYA.PRUDENT_USE.M_RK_RECYCLE_SAME_REUSE', 'SOCI.G5.RESOUR.RESOURCES_IN_KENYA.PRUDENT_USE', 'Mixes up reusing (using again as it is) and recycling (making into something new).', '{"question":"A family uses an empty jerrycan to store water. Is this reusing or recycling?","wrong_answer":"Recycling","correct_answer":"Reusing"}'::jsonb, 'Both words start with "re" and are taught together.', 'Offer "Recycling" next to the right answer and ask the question again in a new context.', 'Sort examples: a jar used again, plastic melted into a bucket.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G5.RESOUR.RESOURCES_IN_KENYA.PRUDENT_USE.M_RK_WATER_ENDLESS', 'SOCI.G5.RESOUR.RESOURCES_IN_KENYA.PRUDENT_USE', 'Thinks water cannot run out because it rains.', '{"question":"Can Kenya run short of water?","wrong_answer":"No, it always rains again","correct_answer":"Yes, in droughts, and when water is wasted or polluted"}'::jsonb, 'The child sees rain return each season.', 'Offer "No, it always rains again" next to the right answer and ask the question again in a new context.', 'Talk about a drought year and dry boreholes in the county.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G5.RESOUR.MINING_IN_KENYA.MINERAL_PLACES.M_MK_PLACE_MIX', 'SOCI.G5.RESOUR.MINING_IN_KENYA.MINERAL_PLACES', 'Places a mineral in the wrong area (soda ash at Lake Nakuru, fluorspar at the coast).', '{"question":"Where in Kenya is soda ash mined?","wrong_answer":"The Kerio Valley","correct_answer":"Lake Magadi"}'::jsonb, 'The child recalls the mineral and a Rift Valley place but mixes them.', 'Offer "The Kerio Valley" next to the right answer and ask the question again in a new context.', 'Link each to a story: soda ash is taken from the lake water at Magadi; fluorspar is dug in the Kerio Valley.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G5.RESOUR.MINING_IN_KENYA.MINERAL_PLACES.M_MK_NOT_MINERAL', 'SOCI.G5.RESOUR.MINING_IN_KENYA.MINERAL_PLACES', 'Counts a crop or timber as a mineral, or says Kenya mines diamonds.', '{"question":"Which of these is a mineral found in Kenya?","wrong_answer":"Coffee","correct_answer":"Gold"}'::jsonb, 'The child treats any export as a mineral.', 'Offer "Coffee" next to the right answer and ask the question again in a new context.', 'Ask whether it was dug from the ground or grown from a seed.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G5.RESOUR.MINING_IN_KENYA.MINERAL_IMPORTANCE.M_MK_USE_MIX', 'SOCI.G5.RESOUR.MINING_IN_KENYA.MINERAL_IMPORTANCE', 'Gives a mineral the wrong use (limestone for jewellery, gemstones for cement).', '{"question":"What is limestone used to make?","wrong_answer":"Jewellery","correct_answer":"Cement"}'::jsonb, 'The child knows the mineral names but not the products.', 'Offer "Jewellery" next to the right answer and ask the question again in a new context.', 'Trace the road from a mineral to a product people see: limestone to cement, gemstone to a ring.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G5.RESOUR.MINING_IN_KENYA.MINERAL_IMPORTANCE.M_MK_NO_HARM', 'SOCI.G5.RESOUR.MINING_IN_KENYA.MINERAL_IMPORTANCE', 'Thinks mining has no bad effects.', '{"question":"What harm can mining cause if it is not controlled?","wrong_answer":"None, mining is always good","correct_answer":"It can damage land and endanger workers"}'::jsonb, 'The child sees only the money.', 'Offer "None, mining is always good" next to the right answer and ask the question again in a new context.', 'Describe an open pit left after mining and ask what it does to farmland.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G5.RESOUR.MINING_IN_KENYA.MINERAL_PLACES.M_MK_MAGADI_NAKURU', 'SOCI.G5.RESOUR.MINING_IN_KENYA.MINERAL_PLACES', 'Mixes Lake Magadi with Lake Nakuru because both are soda lakes in the Rift Valley.', '{"question":"At which lake is soda ash mined?","wrong_answer":"Lake Nakuru","correct_answer":"Lake Magadi"}'::jsonb, 'Both are Rift Valley soda lakes.', 'Offer "Lake Nakuru" next to the right answer and ask the question again in a new context.', 'Put both on the map: Magadi (mining) in the south, Nakuru (flamingos, park) in the centre.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G5.RESOUR.MINING_IN_KENYA.MINERAL_PLACES.M_MK_OIL_COAST', 'SOCI.G5.RESOUR.MINING_IN_KENYA.MINERAL_PLACES', 'Thinks Kenya''s oil was found at the coast because ships carry oil there.', '{"question":"Where was oil found in Kenya?","wrong_answer":"At the coast near Mombasa","correct_answer":"In Turkana"}'::jsonb, 'The child links oil with the port and the refinery.', 'Offer "At the coast near Mombasa" next to the right answer and ask the question again in a new context.', 'Show Turkana on the map and the planned pipeline to the coast.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G5.RESOUR.MINING_IN_KENYA.MINERAL_IMPORTANCE.M_MK_ONLY_MONEY', 'SOCI.G5.RESOUR.MINING_IN_KENYA.MINERAL_IMPORTANCE', 'Thinks minerals are only sold for money and have no use in Kenya.', '{"question":"What is limestone used for in Kenya?","wrong_answer":"Nothing, it is sold abroad","correct_answer":"Making cement for building"}'::jsonb, 'The child knows "minerals earn money" and not their uses.', 'Offer "Nothing, it is sold abroad" next to the right answer and ask the question again in a new context.', 'Show a bag of cement and trace it back to limestone.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G5.RESOUR.MINING_IN_KENYA.MINERAL_IMPORTANCE.M_MK_HOLES_LEFT', 'SOCI.G5.RESOUR.MINING_IN_KENYA.MINERAL_IMPORTANCE', 'Thinks open mining pits can be left after mining because the minerals are gone.', '{"question":"What should happen to a quarry after mining ends?","wrong_answer":"Leave it as it is","correct_answer":"Fill it and plant trees, so it is safe and the land can be used"}'::jsonb, 'The child does not see the danger of open pits.', 'Offer "Leave it as it is" next to the right answer and ask the question again in a new context.', 'Show a photo of a fenced, refilled quarry and an open water-filled pit.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G5.RESOUR.FISHING_IN_KENYA.FISHING_GROUNDS.M_FK_SEA_AS_INLAND', 'SOCI.G5.RESOUR.FISHING_IN_KENYA.FISHING_GROUNDS', 'Counts the Indian Ocean as an inland fishing ground.', '{"question":"Which of these is an inland fishing ground?","wrong_answer":"The Indian Ocean","correct_answer":"Lake Victoria"}'::jsonb, 'The child thinks inland and fishing grounds are the same as any fishing place.', 'Offer "The Indian Ocean" next to the right answer and ask the question again in a new context.', 'Inland means within the country, away from the sea. Sort water bodies on a described map.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G5.RESOUR.FISHING_IN_KENYA.FISHING_GROUNDS.M_FK_SODA_LAKE', 'SOCI.G5.RESOUR.FISHING_IN_KENYA.FISHING_GROUNDS', 'Thinks Lake Magadi, a soda lake, is a main fishing ground.', '{"question":"Which lake is a main fishing ground?","wrong_answer":"Lake Magadi","correct_answer":"Lake Turkana"}'::jsonb, 'The child sees every Rift Valley lake as a fishing lake.', 'Offer "Lake Magadi" next to the right answer and ask the question again in a new context.', 'Ask whether fish can live in water full of soda.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G5.RESOUR.FISHING_IN_KENYA.FISHING_GROUNDS.M_FK_REGION_MIX', 'SOCI.G5.RESOUR.FISHING_IN_KENYA.FISHING_GROUNDS', 'Places a lake in the wrong part of the country (Lake Victoria in the east, Lake Turkana in the south).', '{"question":"Where is Lake Turkana?","wrong_answer":"In the south, near Tanzania","correct_answer":"In the north-west of Kenya"}'::jsonb, 'The child remembers the name without a place.', 'Offer "In the south, near Tanzania" next to the right answer and ask the question again in a new context.', 'Link the lake to the dry north and Lodwar town. Lake Victoria is western.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G5.RESOUR.FISHING_IN_KENYA.FISHING_ECONOMY.M_FK_FOOD_ONLY', 'SOCI.G5.RESOUR.FISHING_IN_KENYA.FISHING_ECONOMY', 'Thinks fishing only gives food to the fishing family.', '{"question":"How does fishing help the country as well as the family?","wrong_answer":"It only feeds the fishing family","correct_answer":"It gives jobs and money from sales"}'::jsonb, 'The child sees fishing at home scale only.', 'Offer "It only feeds the fishing family" next to the right answer and ask the question again in a new context.', 'Follow one fish from the boat to the market, the factory and the plate.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G5.RESOUR.FISHING_IN_KENYA.FISHING_ECONOMY.M_FK_NO_SUSTAIN', 'SOCI.G5.RESOUR.FISHING_IN_KENYA.FISHING_ECONOMY', 'Thinks it is fine to catch all the fish, including the young ones.', '{"question":"Why should fishers not catch young fish?","wrong_answer":"There is no reason","correct_answer":"So that fish can grow and breed for the future"}'::jsonb, 'The child sees only today''s catch.', 'Offer "There is no reason" next to the right answer and ask the question again in a new context.', 'Compare catching all the chickens with keeping some to lay eggs.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G5.RESOUR.FISHING_IN_KENYA.FISHING_GROUNDS.M_FK_RIVER_NOT', 'SOCI.G5.RESOUR.FISHING_IN_KENYA.FISHING_GROUNDS', 'Thinks fish come only from lakes and the sea, not from dams and fish ponds.', '{"question":"Can fish be farmed in Kenya?","wrong_answer":"No, fish only come from lakes","correct_answer":"Yes, in fish ponds and dams"}'::jsonb, 'The child knows only fishing from boats.', 'Offer "No, fish only come from lakes" next to the right answer and ask the question again in a new context.', 'Show a photo of a fish pond in a farmer''s shamba.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G5.RESOUR.FISHING_IN_KENYA.FISHING_ECONOMY.M_FK_EXPORT_NONE', 'SOCI.G5.RESOUR.FISHING_IN_KENYA.FISHING_ECONOMY', 'Thinks fish caught in Kenya are never sold to other countries.', '{"question":"Is Nile perch from Lake Victoria sold abroad?","wrong_answer":"No, only in Kenya","correct_answer":"Yes, as fillets to other countries"}'::jsonb, 'The child sees fish only at the local market.', 'Offer "No, only in Kenya" next to the right answer and ask the question again in a new context.', 'Trace the route of Nile perch fillets from Kisumu to the airport.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G5.RESOUR.FISHING_IN_KENYA.FISHING_ECONOMY.M_FK_NET_ANY', 'SOCI.G5.RESOUR.FISHING_IN_KENYA.FISHING_ECONOMY', 'Thinks any net is fine for fishing.', '{"question":"Why is a net with very small holes bad for fishing?","wrong_answer":"It is not; it catches more fish","correct_answer":"It catches young fish, so fewer fish grow up"}'::jsonb, 'More fish today seems better.', 'Offer "It is not; it catches more fish" next to the right answer and ask the question again in a new context.', 'Pour beans and rice through two sieves: the fine one keeps even the smallest.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G5.RESOUR.WILDLIFE_AND_TOURISM_IN_.ATTRACTIONS_PLACES.M_WT_PLACE_MIX', 'SOCI.G5.RESOUR.WILDLIFE_AND_TOURISM_IN_.ATTRACTIONS_PLACES', 'Places a park in the wrong part of Kenya (Amboseli in the north, Maasai Mara at the coast).', '{"question":"In which county is the Maasai Mara?","wrong_answer":"Kajiado","correct_answer":"Narok"}'::jsonb, 'The child remembers southern Rift parks but mixes them.', 'Offer "Kajiado" next to the right answer and ask the question again in a new context.', 'Link them to a story: the Mara is where the wildebeest cross; Amboseli looks at Kilimanjaro.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G5.RESOUR.WILDLIFE_AND_TOURISM_IN_.ATTRACTIONS_PLACES.M_WT_ANIMAL_MIX', 'SOCI.G5.RESOUR.WILDLIFE_AND_TOURISM_IN_.ATTRACTIONS_PLACES', 'Gives a park the wrong animal (flamingos at Amboseli, wildebeest at Lake Nakuru).', '{"question":"For which birds is Lake Nakuru National Park famous?","wrong_answer":"Ostriches","correct_answer":"Flamingos"}'::jsonb, 'The child knows the park names but not what is special.', 'Offer "Ostriches" next to the right answer and ask the question again in a new context.', 'Tell the one thing each park is famous for.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G5.RESOUR.WILDLIFE_AND_TOURISM_IN_.TOURISM_ECONOMY.M_WT_HOTELS_ONLY', 'SOCI.G5.RESOUR.WILDLIFE_AND_TOURISM_IN_.TOURISM_ECONOMY', 'Thinks only hotel owners gain from tourism.', '{"question":"Who earns from tourism besides hotel owners?","wrong_answer":"No one else","correct_answer":"Guides, drivers and craft sellers"}'::jsonb, 'The child sees the biggest businesses only.', 'Offer "No one else" next to the right answer and ask the question again in a new context.', 'List ten jobs on a day trip to a park.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G5.RESOUR.WILDLIFE_AND_TOURISM_IN_.TOURISM_ECONOMY.M_WT_ANIMALS_NO_VALUE', 'SOCI.G5.RESOUR.WILDLIFE_AND_TOURISM_IN_.TOURISM_ECONOMY', 'Thinks wildlife brings no benefit and the land would be better for farming.', '{"question":"Why does Kenya protect its wildlife?","wrong_answer":"Animals bring no benefit","correct_answer":"Wildlife brings tourists and money to the country"}'::jsonb, 'The child sees the park as unused land.', 'Offer "Animals bring no benefit" next to the right answer and ask the question again in a new context.', 'Compare the income of a park visit with a small farm''s harvest.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G5.RESOUR.WILDLIFE_AND_TOURISM_IN_.ATTRACTIONS_PLACES.M_WT_ONLY_ANIMALS', 'SOCI.G5.RESOUR.WILDLIFE_AND_TOURISM_IN_.ATTRACTIONS_PLACES', 'Thinks tourists come to Kenya only to see wild animals.', '{"question":"Name a tourist attraction in Kenya that is not wildlife.","wrong_answer":"There is none","correct_answer":"Beaches, Fort Jesus, Mount Kenya, or cultural sites"}'::jsonb, 'Tourism is taught beside wildlife.', 'Offer "There is none" next to the right answer and ask the question again in a new context.', 'List attractions at the coast and in the mountains.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G5.RESOUR.WILDLIFE_AND_TOURISM_IN_.ATTRACTIONS_PLACES.M_WT_PARK_RESERVE', 'SOCI.G5.RESOUR.WILDLIFE_AND_TOURISM_IN_.ATTRACTIONS_PLACES', 'Thinks a national park and a game reserve are the same thing.', '{"question":"Who manages the Maasai Mara National Reserve?","wrong_answer":"The Kenya Wildlife Service, like every park","correct_answer":"The county government, because it is a reserve"}'::jsonb, 'Both protect animals and look alike to visitors.', 'Offer "The Kenya Wildlife Service, like every park" next to the right answer and ask the question again in a new context.', 'Compare: national parks are run by the national government (KWS); reserves by counties.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G5.RESOUR.WILDLIFE_AND_TOURISM_IN_.TOURISM_ECONOMY.M_WT_POACHING_OK', 'SOCI.G5.RESOUR.WILDLIFE_AND_TOURISM_IN_.TOURISM_ECONOMY', 'Thinks killing a few animals for their tusks or horns does not harm tourism.', '{"question":"How does poaching elephants harm Kenya?","wrong_answer":"It does not; there are many elephants","correct_answer":"Fewer elephants means fewer tourists and less money for the country"}'::jsonb, 'The child does not link one animal to the whole tourist trade.', 'Offer "It does not; there are many elephants" next to the right answer and ask the question again in a new context.', 'Show elephant numbers falling in a poaching period.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G5.RESOUR.WILDLIFE_AND_TOURISM_IN_.TOURISM_ECONOMY.M_WT_FOREIGN_ONLY', 'SOCI.G5.RESOUR.WILDLIFE_AND_TOURISM_IN_.TOURISM_ECONOMY', 'Thinks only foreigners are tourists.', '{"question":"Can Kenyan families be tourists in Kenya?","wrong_answer":"No, tourists are only foreigners","correct_answer":"Yes: local tourists visit parks and beaches too"}'::jsonb, 'Tourists on television are foreigners.', 'Offer "No, tourists are only foreigners" next to the right answer and ask the question again in a new context.', 'Talk about school trips and holidays to parks.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G5.RESOUR.DEVELOPMENT_OF_TRANSPORT.EARLY_TRANSPORT.M_TR_EARLY_MODERN_MIX', 'SOCI.G5.RESOUR.DEVELOPMENT_OF_TRANSPORT.EARLY_TRANSPORT', 'Treats trains, lorries or aeroplanes as early means of transport.', '{"question":"Which was an early means of transport in Kenya?","wrong_answer":"A lorry","correct_answer":"A donkey"}'::jsonb, 'The child does not tell old from new.', 'Offer "A lorry" next to the right answer and ask the question again in a new context.', 'Sort cards by what the grandparents'' grandparents could have used.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G5.RESOUR.DEVELOPMENT_OF_TRANSPORT.EARLY_TRANSPORT.M_TR_WALK_NOT_TRANSPORT', 'SOCI.G5.RESOUR.DEVELOPMENT_OF_TRANSPORT.EARLY_TRANSPORT', 'Thinks carrying loads on the head or back does not count as transport.', '{"question":"How did people move goods before roads and lorries?","wrong_answer":"They did not move goods","correct_answer":"They carried loads on their heads and backs, or used animals"}'::jsonb, 'The child thinks transport needs a machine.', 'Offer "They did not move goods" next to the right answer and ask the question again in a new context.', 'Ask how salt reached an inland home a hundred years ago.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G5.RESOUR.DEVELOPMENT_OF_TRANSPORT.MODERN_TRANSPORT.M_TR_MODE_MIX', 'SOCI.G5.RESOUR.DEVELOPMENT_OF_TRANSPORT.MODERN_TRANSPORT', 'Chooses a means of transport that does not suit the job (a ferry to cross land, a lorry to cross a lake).', '{"question":"Which is the best way to carry many tonnes of fuel across the country?","wrong_answer":"A bicycle","correct_answer":"A pipeline or a tanker lorry"}'::jsonb, 'The child links "carry" with any vehicle.', 'Offer "A bicycle" next to the right answer and ask the question again in a new context.', 'Compare tonnes and speed: a big load, a long way, or a small fast parcel.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G5.RESOUR.DEVELOPMENT_OF_TRANSPORT.MODERN_TRANSPORT.M_TR_SGR_FIRST', 'SOCI.G5.RESOUR.DEVELOPMENT_OF_TRANSPORT.MODERN_TRANSPORT', 'Thinks the Standard Gauge Railway is the first railway in Kenya.', '{"question":"Which railway was built first in Kenya?","wrong_answer":"The Standard Gauge Railway","correct_answer":"The railway from Mombasa to Kisumu"}'::jsonb, 'The child knows the new railway and not the old one.', 'Offer "The Standard Gauge Railway" next to the right answer and ask the question again in a new context.', 'Tell the story of the railway built from Mombasa toward Lake Victoria over 100 years ago.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G5.RESOUR.DEVELOPMENT_OF_TRANSPORT.ROAD_SAFETY.M_TR_CROSS_ANYWHERE', 'SOCI.G5.RESOUR.DEVELOPMENT_OF_TRANSPORT.ROAD_SAFETY', 'Thinks it is safe to cross a road anywhere if it looks empty.', '{"question":"Where is the safest place to cross the road?","wrong_answer":"Anywhere, if the road looks empty","correct_answer":"At a zebra crossing or footbridge"}'::jsonb, 'The child trusts what he sees at one moment.', 'Offer "Anywhere, if the road looks empty" next to the right answer and ask the question again in a new context.', 'Ask what a driver at speed can see around a bend.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G5.RESOUR.DEVELOPMENT_OF_TRANSPORT.ROAD_SAFETY.M_TR_BELT_LATER', 'SOCI.G5.RESOUR.DEVELOPMENT_OF_TRANSPORT.ROAD_SAFETY', 'Thinks a seat belt or helmet is only needed on long trips.', '{"question":"When should a boda boda rider and passenger wear helmets?","wrong_answer":"Only on long trips","correct_answer":"On every trip"}'::jsonb, 'The child thinks short trips are safe.', 'Offer "Only on long trips" next to the right answer and ask the question again in a new context.', 'Ask how fast a crash can happen on a short road.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G5.RESOUR.DEVELOPMENT_OF_TRANSPORT.EARLY_TRANSPORT.M_TR_DHOW_MODERN', 'SOCI.G5.RESOUR.DEVELOPMENT_OF_TRANSPORT.EARLY_TRANSPORT', 'Thinks the dhow is a modern ship because it is still used today.', '{"question":"Is the dhow an early or a modern means of transport?","wrong_answer":"Modern, it is still used in Lamu","correct_answer":"Early; it has been used for hundreds of years and is still used"}'::jsonb, 'The child thinks anything used today is modern.', 'Offer "Modern, it is still used in Lamu" next to the right answer and ask the question again in a new context.', 'Put the dhow on a timeline beside the ship and the aeroplane.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G5.RESOUR.DEVELOPMENT_OF_TRANSPORT.EARLY_TRANSPORT.M_TR_ANIMAL_NOT', 'SOCI.G5.RESOUR.DEVELOPMENT_OF_TRANSPORT.EARLY_TRANSPORT', 'Does not count donkeys and camels as transport.', '{"question":"Is a donkey carrying water a means of transport?","wrong_answer":"No, it is just an animal","correct_answer":"Yes, animal transport"}'::jsonb, 'The child thinks transport must be a vehicle.', 'Offer "No, it is just an animal" next to the right answer and ask the question again in a new context.', 'Ask how water reaches a home with no tap and no car.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G5.RESOUR.DEVELOPMENT_OF_TRANSPORT.MODERN_TRANSPORT.M_TR_PIPELINE_NOT', 'SOCI.G5.RESOUR.DEVELOPMENT_OF_TRANSPORT.MODERN_TRANSPORT', 'Does not count a pipeline as a means of transport.', '{"question":"How is oil moved from Mombasa to Nairobi?","wrong_answer":"Only by lorries","correct_answer":"Mostly by pipeline, and also by lorries"}'::jsonb, 'A pipeline does not move, so it does not look like transport.', 'Offer "Only by lorries" next to the right answer and ask the question again in a new context.', 'Show the pipeline route on the map.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G5.RESOUR.DEVELOPMENT_OF_TRANSPORT.MODERN_TRANSPORT.M_TR_AIR_HEAVY', 'SOCI.G5.RESOUR.DEVELOPMENT_OF_TRANSPORT.MODERN_TRANSPORT', 'Chooses air transport for heavy, bulky goods such as cement or maize over a long distance.', '{"question":"Which is best for carrying 1,000 bags of cement from Mombasa to Nairobi?","wrong_answer":"An aeroplane, it is fastest","correct_answer":"The railway or lorries"}'::jsonb, 'The child picks the fastest means without weighing cost and load.', 'Offer "An aeroplane, it is fastest" next to the right answer and ask the question again in a new context.', 'Compare the cost of flying one bag with sending it by train.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G5.RESOUR.DEVELOPMENT_OF_TRANSPORT.ROAD_SAFETY.M_TR_PHONE_CROSS', 'SOCI.G5.RESOUR.DEVELOPMENT_OF_TRANSPORT.ROAD_SAFETY', 'Thinks it is safe to cross a road while using a phone or with earphones in.', '{"question":"Is it safe to cross the road while looking at a phone?","wrong_answer":"Yes, if you walk fast","correct_answer":"No, you cannot see or hear the traffic"}'::jsonb, 'The child thinks speed makes up for not looking.', 'Offer "Yes, if you walk fast" next to the right answer and ask the question again in a new context.', 'Act it: one learner crosses looking at a "phone" while another plays a car.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G5.RESOUR.DEVELOPMENT_OF_TRANSPORT.ROAD_SAFETY.M_TR_BODABODA_THREE', 'SOCI.G5.RESOUR.DEVELOPMENT_OF_TRANSPORT.ROAD_SAFETY', 'Thinks it is fine for three or more passengers to ride on one boda boda.', '{"question":"How many passengers may ride on a boda boda?","wrong_answer":"As many as fit","correct_answer":"One, wearing a helmet"}'::jsonb, 'The child often sees boda bodas carrying many people.', 'Offer "As many as fit" next to the right answer and ask the question again in a new context.', 'Show the rule and ask why extra people make it unstable.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G5.RESOUR.DEVELOPMENT_OF_COMMUNICA.EARLY_COMMUNICATION.M_CM_EARLY_MODERN_MIX', 'SOCI.G5.RESOUR.DEVELOPMENT_OF_COMMUNICA.EARLY_COMMUNICATION', 'Treats a telephone, radio or email as an early form of communication.', '{"question":"Which was an early form of communication in Kenya?","wrong_answer":"Email","correct_answer":"A drum"}'::jsonb, 'The child cannot tell old from new.', 'Offer "Email" next to the right answer and ask the question again in a new context.', 'Ask what was used before electricity.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G5.RESOUR.DEVELOPMENT_OF_COMMUNICA.EARLY_COMMUNICATION.M_CM_EARLY_FAST', 'SOCI.G5.RESOUR.DEVELOPMENT_OF_COMMUNICA.EARLY_COMMUNICATION', 'Thinks early forms reached as far and as fast as modern ones.', '{"question":"Why is a mobile phone faster than a messenger on foot?","wrong_answer":"It is not faster","correct_answer":"It sends the message at once over a long distance"}'::jsonb, 'The child does not compare speed.', 'Offer "It is not faster" next to the right answer and ask the question again in a new context.', 'Time a runner and a phone call across the same distance.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G5.RESOUR.DEVELOPMENT_OF_COMMUNICA.MODERN_COMMUNICATION.M_CM_MEDIUM_MIX', 'SOCI.G5.RESOUR.DEVELOPMENT_OF_COMMUNICA.MODERN_COMMUNICATION', 'Mixes up the means (says radio shows pictures, or a newspaper plays sound).', '{"question":"Which means of communication shows pictures and sound together?","wrong_answer":"Radio","correct_answer":"Television"}'::jsonb, 'The child knows the names but not what each does.', 'Offer "Radio" next to the right answer and ask the question again in a new context.', 'Describe what you can see and hear on each in a one-line list.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G5.RESOUR.DEVELOPMENT_OF_COMMUNICA.MODERN_COMMUNICATION.M_CM_NO_RISK', 'SOCI.G5.RESOUR.DEVELOPMENT_OF_COMMUNICA.MODERN_COMMUNICATION', 'Thinks everything on the internet or a phone message is true and safe.', '{"question":"You get a message that claims something shocking. What should you do first?","wrong_answer":"Share it with everyone","correct_answer":"Check if it is true with a trusted adult or source"}'::jsonb, 'The child trusts what he reads.', 'Offer "Share it with everyone" next to the right answer and ask the question again in a new context.', 'Practise with a made-up rumour and ask who could check it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G5.RESOUR.DEVELOPMENT_OF_COMMUNICA.EARLY_COMMUNICATION.M_CM_DRUM_MUSIC_ONLY', 'SOCI.G5.RESOUR.DEVELOPMENT_OF_COMMUNICA.EARLY_COMMUNICATION', 'Thinks drums were used only for music and dancing.', '{"question":"How did some communities use drums besides music?","wrong_answer":"Only for dancing","correct_answer":"To send messages and warnings over a distance"}'::jsonb, 'The child has seen drums only at celebrations.', 'Offer "Only for dancing" next to the right answer and ask the question again in a new context.', 'Beat two patterns: one for "come" and one for "danger".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G5.RESOUR.DEVELOPMENT_OF_COMMUNICA.EARLY_COMMUNICATION.M_CM_SMOKE_NIGHT', 'SOCI.G5.RESOUR.DEVELOPMENT_OF_COMMUNICA.EARLY_COMMUNICATION', 'Thinks smoke signals worked best at night.', '{"question":"When could smoke signals be seen best?","wrong_answer":"At night","correct_answer":"In the day, in clear weather"}'::jsonb, 'The child pictures fire glowing at night.', 'Offer "At night" next to the right answer and ask the question again in a new context.', 'Ask whether you can see grey smoke in the dark.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G5.RESOUR.DEVELOPMENT_OF_COMMUNICA.MODERN_COMMUNICATION.M_CM_INTERNET_EVERYWHERE', 'SOCI.G5.RESOUR.DEVELOPMENT_OF_COMMUNICA.MODERN_COMMUNICATION', 'Thinks everyone in Kenya can use the internet, so the radio is no longer needed.', '{"question":"Why is radio still important in Kenya?","wrong_answer":"It is not; everyone has internet","correct_answer":"It reaches people without electricity or internet, in many languages"}'::jsonb, 'The child''s own family may have phones and internet.', 'Offer "It is not; everyone has internet" next to the right answer and ask the question again in a new context.', 'Ask how a herder far from town hears the news.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G5.RESOUR.DEVELOPMENT_OF_COMMUNICA.MODERN_COMMUNICATION.M_CM_SHARE_DETAILS', 'SOCI.G5.RESOUR.DEVELOPMENT_OF_COMMUNICA.MODERN_COMMUNICATION', 'Thinks it is fine to share a home address or school name with a stranger online.', '{"question":"Someone you do not know asks for your address on a phone app. What do you do?","wrong_answer":"Send it, they are friendly","correct_answer":"Do not send it, and tell a parent or teacher"}'::jsonb, 'The child trusts friendly words.', 'Offer "Send it, they are friendly" next to the right answer and ask the question again in a new context.', 'Practise saying no and telling an adult.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G5.POLITI.TRADITIONAL_LEADERS_IN_K.LEADER_FACTS.M_TL_COMMUNITY_MIX', 'SOCI.G5.POLITI.TRADITIONAL_LEADERS_IN_K.LEADER_FACTS', 'Gives a leader the wrong community (Mekatilili as Maasai, Koitalel as Luo).', '{"question":"Mekatilili wa Menza led which community?","wrong_answer":"The Maasai","correct_answer":"The Giriama"}'::jsonb, 'The child recalls a famous name without its community.', 'Offer "The Maasai" next to the right answer and ask the question again in a new context.', 'Link each leader with a map place: Mekatilili at the coast, Koitalel in the Nandi hills.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G5.POLITI.TRADITIONAL_LEADERS_IN_K.LEADER_FACTS.M_TL_ROLE_MIX', 'SOCI.G5.POLITI.TRADITIONAL_LEADERS_IN_K.LEADER_FACTS', 'Mixes what each leader did (Nabongo Mumia led the Nandi resistance).', '{"question":"Which leader of the Nandi resisted the building of the railway?","wrong_answer":"Nabongo Mumia","correct_answer":"Koitalel Arap Samoei"}'::jsonb, 'The child links all famous leaders to the same story.', 'Offer "Nabongo Mumia" next to the right answer and ask the question again in a new context.', 'Compare two leaders: one resisted, one welcomed visitors.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G5.POLITI.TRADITIONAL_LEADERS_IN_K.LEADER_QUALITIES.M_TL_FEAR_LEADER', 'SOCI.G5.POLITI.TRADITIONAL_LEADERS_IN_K.LEADER_QUALITIES', 'Thinks a good leader is the one people fear.', '{"question":"Which quality makes a good traditional leader?","wrong_answer":"Making people afraid","correct_answer":"Wisdom and fairness"}'::jsonb, 'The child links power with fear.', 'Offer "Making people afraid" next to the right answer and ask the question again in a new context.', 'Ask whom a villager would go to for help and why.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G5.POLITI.TRADITIONAL_LEADERS_IN_K.LEADER_QUALITIES.M_TL_NO_ROLE_TODAY', 'SOCI.G5.POLITI.TRADITIONAL_LEADERS_IN_K.LEADER_QUALITIES', 'Thinks traditional leaders and elders have no role today.', '{"question":"What do elders still do in many communities today?","wrong_answer":"Nothing, they have no role","correct_answer":"Settle disputes and guide ceremonies"}'::jsonb, 'The child thinks old leaders are only a thing of the past.', 'Offer "Nothing, they have no role" next to the right answer and ask the question again in a new context.', 'Ask who settles a quarrel between neighbours first.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G5.POLITI.TRADITIONAL_LEADERS_IN_K.LEADER_FACTS.M_TL_MEKATILILI_MAN', 'SOCI.G5.POLITI.TRADITIONAL_LEADERS_IN_K.LEADER_FACTS', 'Thinks Mekatilili wa Menza was a man.', '{"question":"Was Mekatilili wa Menza a man or a woman?","wrong_answer":"A man","correct_answer":"A woman"}'::jsonb, 'The child expects resistance leaders to be men.', 'Offer "A man" next to the right answer and ask the question again in a new context.', 'Show the statue of Mekatilili in Malindi.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G5.POLITI.TRADITIONAL_LEADERS_IN_K.LEADER_FACTS.M_TL_ALL_RESISTED', 'SOCI.G5.POLITI.TRADITIONAL_LEADERS_IN_K.LEADER_FACTS', 'Thinks every traditional leader fought the British.', '{"question":"Did Nabongo Mumia fight the British?","wrong_answer":"Yes, all leaders fought them","correct_answer":"No, he worked with the British"}'::jsonb, 'Resistance stories are the most told.', 'Offer "Yes, all leaders fought them" next to the right answer and ask the question again in a new context.', 'Sort leaders: resisted or worked with.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G5.POLITI.TRADITIONAL_LEADERS_IN_K.LEADER_QUALITIES.M_TL_QUALITY_DEED_MIX', 'SOCI.G5.POLITI.TRADITIONAL_LEADERS_IN_K.LEADER_QUALITIES', 'Names a quality that the leader''s deed does not show.', '{"question":"Mekatilili spoke against forced labour though she could be punished. Which quality does this show?","wrong_answer":"Wealth","correct_answer":"Courage"}'::jsonb, 'The child picks a quality word without linking it to the deed.', 'Offer "Wealth" next to the right answer and ask the question again in a new context.', 'Ask: what did she risk? What do we call facing risk for others?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G5.POLITI.TRADITIONAL_LEADERS_IN_K.LEADER_QUALITIES.M_TL_ELDERS_ONLY_OLD', 'SOCI.G5.POLITI.TRADITIONAL_LEADERS_IN_K.LEADER_QUALITIES', 'Thinks elders today only tell old stories and have no real duties.', '{"question":"What do elders do in many communities today?","wrong_answer":"Nothing, they only tell stories","correct_answer":"Settle disputes, guide ceremonies and teach values"}'::jsonb, 'The child sees elders as grandparents only.', 'Offer "Nothing, they only tell stories" next to the right answer and ask the question again in a new context.', 'Invite an elder to say what they did this month.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G5.POLITI.EARLY_FORMS_OF_GOVERNM_E.EARLY_FORMS.M_EG_NO_GOVT', 'SOCI.G5.POLITI.EARLY_FORMS_OF_GOVERNM_E.EARLY_FORMS', 'Thinks Kenyan communities had no government before colonial rule.', '{"question":"How were communities governed before colonial rule?","wrong_answer":"They had no government","correct_answer":"By councils of elders and other leaders"}'::jsonb, 'The child thinks government means a modern state.', 'Offer "They had no government" next to the right answer and ask the question again in a new context.', 'Ask who settled disputes and made rules in a village before colonial rule.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G5.POLITI.EARLY_FORMS_OF_GOVERNM_E.EARLY_FORMS.M_EG_KING_ALL', 'SOCI.G5.POLITI.EARLY_FORMS_OF_GOVERNM_E.EARLY_FORMS', 'Thinks every community was ruled by a king.', '{"question":"Which of these communities was ruled by a king?","wrong_answer":"The Maasai","correct_answer":"The Wanga"}'::jsonb, 'The child knows kings from stories and applies them to all.', 'Offer "The Maasai" next to the right answer and ask the question again in a new context.', 'Compare the Wanga kingdom with the council-ruled Ameru.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G5.POLITI.EARLY_FORMS_OF_GOVERNM_E.MAASAI_AMERU.M_EG_SAME_NAMES', 'SOCI.G5.POLITI.EARLY_FORMS_OF_GOVERNM_E.MAASAI_AMERU', 'Mixes the titles (Njuri Ncheke as Maasai, Laibon as Ameru).', '{"question":"What was the council of elders of the Ameru called?","wrong_answer":"Laibon","correct_answer":"Njuri Ncheke"}'::jsonb, 'The child knows the names but not which belongs to which.', 'Offer "Laibon" next to the right answer and ask the question again in a new context.', 'Link the Maasai laibon to the spiritual leader and the Njuri Ncheke to the Ameru elders.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G5.POLITI.EARLY_FORMS_OF_GOVERNM_E.MAASAI_AMERU.M_EG_ONE_RULER', 'SOCI.G5.POLITI.EARLY_FORMS_OF_GOVERNM_E.MAASAI_AMERU', 'Thinks the laibon or the Mugwe ruled alone as a king.', '{"question":"How was the Maasai laibon different from a king?","wrong_answer":"He ruled alone as a king","correct_answer":"He guided spiritually while elders made decisions"}'::jsonb, 'The child thinks a leader with a title has total power.', 'Offer "He ruled alone as a king" next to the right answer and ask the question again in a new context.', 'Ask who made decisions about cattle raids and grazing.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G5.POLITI.EARLY_FORMS_OF_GOVERNM_E.LESSONS.M_EG_OLD_USELESS', 'SOCI.G5.POLITI.EARLY_FORMS_OF_GOVERNM_E.LESSONS', 'Thinks nothing from early government applies to today.', '{"question":"Which practice from early government is still useful today?","wrong_answer":"None of them","correct_answer":"Settling quarrels by talk and mediation"}'::jsonb, 'The child sees early government as outdated.', 'Offer "None of them" next to the right answer and ask the question again in a new context.', 'Match each old practice to a modern office.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G5.POLITI.EARLY_FORMS_OF_GOVERNM_E.LESSONS.M_EG_COPY_ALL', 'SOCI.G5.POLITI.EARLY_FORMS_OF_GOVERNM_E.LESSONS', 'Thinks modern government should copy everything from early government, including harsh punishments.', '{"question":"Which old practice should NOT be copied today?","wrong_answer":"Consulting elders","correct_answer":"Punishments that hurt people"}'::jsonb, 'The child sees all old practices as good.', 'Offer "Consulting elders" next to the right answer and ask the question again in a new context.', 'Sort practices into keep and leave behind with reasons.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G5.POLITI.EARLY_FORMS_OF_GOVERNM_E.EARLY_FORMS.M_EG_AGE_SET_SCHOOL', 'SOCI.G5.POLITI.EARLY_FORMS_OF_GOVERNM_E.EARLY_FORMS', 'Thinks an age-set was a school class.', '{"question":"What was an age-set?","wrong_answer":"A class at school","correct_answer":"A group of people initiated at the same time, with duties for their age"}'::jsonb, 'The child links "same age" with "same class".', 'Offer "A class at school" next to the right answer and ask the question again in a new context.', 'Compare: your class learns together; an age-set had duties together, like defending the community.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G5.POLITI.EARLY_FORMS_OF_GOVERNM_E.EARLY_FORMS.M_EG_KING_WANGA_ALL', 'SOCI.G5.POLITI.EARLY_FORMS_OF_GOVERNM_E.EARLY_FORMS', 'Thinks the Wanga had no king because no Kenyan community had kings.', '{"question":"Which Kenyan community had a king?","wrong_answer":"None did","correct_answer":"The Wanga, led by the Nabongo"}'::jsonb, 'The child has overcorrected from "most had councils" to "none had kings".', 'Offer "None did" next to the right answer and ask the question again in a new context.', 'Show Mumias and the Nabongo title.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G5.POLITI.EARLY_FORMS_OF_GOVERNM_E.MAASAI_AMERU.M_EG_MORAN_RULE', 'SOCI.G5.POLITI.EARLY_FORMS_OF_GOVERNM_E.MAASAI_AMERU', 'Thinks the morans (warriors) ruled the Maasai.', '{"question":"What was the main duty of Maasai morans?","wrong_answer":"To rule the community","correct_answer":"To defend the community and its cattle"}'::jsonb, 'Warriors are the most visible group in stories.', 'Offer "To rule the community" next to the right answer and ask the question again in a new context.', 'Sort duties: elders decided, morans defended, the laibon guided.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G5.POLITI.EARLY_FORMS_OF_GOVERNM_E.MAASAI_AMERU.M_EG_NJURI_COURT_NONE', 'SOCI.G5.POLITI.EARLY_FORMS_OF_GOVERNM_E.MAASAI_AMERU', 'Thinks the Njuri Ncheke only met for ceremonies and did not judge cases.', '{"question":"What did the Njuri Ncheke do?","wrong_answer":"Only led dances","correct_answer":"Judged cases and made rules for the Ameru"}'::jsonb, 'The child hears of the council at cultural events today.', 'Offer "Only led dances" next to the right answer and ask the question again in a new context.', 'Read a short story of the council settling a land case.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G5.POLITI.EARLY_FORMS_OF_GOVERNM_E.LESSONS.M_EG_LESSON_MATCH', 'SOCI.G5.POLITI.EARLY_FORMS_OF_GOVERNM_E.LESSONS', 'Links an early practice to the wrong modern practice (age-sets to elections).', '{"question":"Elders settled quarrels by listening to both sides. Which modern practice is like this?","wrong_answer":"Elections","correct_answer":"Mediation in courts or by chiefs"}'::jsonb, 'The child picks any modern practice.', 'Offer "Elections" next to the right answer and ask the question again in a new context.', 'Match practice and today in pairs on the board.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G5.POLITI.EARLY_FORMS_OF_GOVERNM_E.LESSONS.M_EG_YOUTH_NO_ROLE', 'SOCI.G5.POLITI.EARLY_FORMS_OF_GOVERNM_E.LESSONS', 'Thinks young people had no duties in early government, so youth today have no part to play in governance.', '{"question":"Which duty did young people have in many early Kenyan communities?","wrong_answer":"None; only elders mattered","correct_answer":"Defending the community and doing work for it, by age-set"}'::jsonb, 'The child hears that elders decided and forgets the age-sets.', 'Offer "None; only elders mattered" next to the right answer and ask the question again in a new context.', 'Link age-set duties to youth service and youth leaders today.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G5.POLITI.CITIZENSHIP_IN_KENYA.HOW_CITIZEN.M_CZ_BORN_IN_KENYA_ONLY', 'SOCI.G5.POLITI.CITIZENSHIP_IN_KENYA.HOW_CITIZEN', 'Thinks a person must be born inside Kenya to be a citizen by birth.', '{"question":"Aisha was born abroad. Her mother is a Kenyan citizen. Is Aisha a Kenyan citizen by birth?","wrong_answer":"No, she was not born in Kenya","correct_answer":"Yes, because one parent is a Kenyan citizen"}'::jsonb, 'The child links citizenship with place of birth only.', 'Offer "No, she was not born in Kenya" next to the right answer and ask the question again in a new context.', 'Use two stories: one born in Kenya, one born abroad to a Kenyan parent.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G5.POLITI.CITIZENSHIP_IN_KENYA.HOW_CITIZEN.M_CZ_ID_MAKES', 'SOCI.G5.POLITI.CITIZENSHIP_IN_KENYA.HOW_CITIZEN', 'Thinks getting an ID card or passport is what makes a person a citizen.', '{"question":"What makes a person a citizen?","wrong_answer":"Having an ID card","correct_answer":"Being born to a citizen or registered as one"}'::jsonb, 'The child confuses the paper with the status.', 'Offer "Having an ID card" next to the right answer and ask the question again in a new context.', 'Ask: is a baby a citizen? Does she have an ID?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G5.POLITI.CITIZENSHIP_IN_KENYA.HOW_CITIZEN.M_CZ_MARRIAGE_INSTANT', 'SOCI.G5.POLITI.CITIZENSHIP_IN_KENYA.HOW_CITIZEN', 'Thinks marrying a Kenyan makes a person a citizen on the wedding day.', '{"question":"A foreign woman marries a Kenyan man. When can she apply for citizenship by registration?","wrong_answer":"The same day","correct_answer":"After a period set by law, seven years"}'::jsonb, 'The child skips the waiting period.', 'Offer "The same day" next to the right answer and ask the question again in a new context.', 'Tell the story with the years in order.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G5.POLITI.CITIZENSHIP_IN_KENYA.DUAL.M_CZ_ONE_PASSPORT', 'SOCI.G5.POLITI.CITIZENSHIP_IN_KENYA.DUAL', 'Thinks Kenya does not allow a person to hold two nationalities.', '{"question":"Can a Kenyan citizen also be a citizen of another country?","wrong_answer":"No, Kenya does not allow it","correct_answer":"Yes, the 2010 Constitution allows dual citizenship"}'::jsonb, 'The child recalls older rules from older people.', 'Offer "No, Kenya does not allow it" next to the right answer and ask the question again in a new context.', 'Ask: what year is the Constitution?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G5.POLITI.CITIZENSHIP_IN_KENYA.DUAL.M_CZ_DUAL_LOSE', 'SOCI.G5.POLITI.CITIZENSHIP_IN_KENYA.DUAL', 'Thinks a citizen by birth loses Kenyan citizenship by taking another nationality.', '{"question":"A Kenyan by birth takes the citizenship of another country. What happens to her Kenyan citizenship?","wrong_answer":"She loses it","correct_answer":"She keeps it"}'::jsonb, 'The child thinks one nationality cancels the other.', 'Offer "She loses it" next to the right answer and ask the question again in a new context.', 'Use a two-flag picture: two homes, one family.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G5.POLITI.CITIZENSHIP_IN_KENYA.GOOD_CITIZEN.M_CZ_ONLY_VOTING', 'SOCI.G5.POLITI.CITIZENSHIP_IN_KENYA.GOOD_CITIZEN', 'Thinks a good citizen is only someone who votes.', '{"question":"Which action shows good citizenship for a child?","wrong_answer":"Waiting until age 18 to do anything","correct_answer":"Keeping the school compound clean and obeying rules"}'::jsonb, 'The child thinks citizenship begins at voting age.', 'Offer "Waiting until age 18 to do anything" next to the right answer and ask the question again in a new context.', 'List things a ten-year-old can do for the school and the village.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G5.POLITI.CITIZENSHIP_IN_KENYA.GOOD_CITIZEN.M_CZ_RIGHTS_NO_DUTY', 'SOCI.G5.POLITI.CITIZENSHIP_IN_KENYA.GOOD_CITIZEN', 'Thinks citizens have rights but no duties.', '{"question":"Which is a duty of a citizen?","wrong_answer":"To do whatever one likes","correct_answer":"To obey the law"}'::jsonb, 'The child hears the word rights more than duties.', 'Offer "To do whatever one likes" next to the right answer and ask the question again in a new context.', 'Pair every right with a duty in a two-column list.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G5.POLITI.CITIZENSHIP_IN_KENYA.HOW_CITIZEN.M_CZ_LIVE_LONG_AUTO', 'SOCI.G5.POLITI.CITIZENSHIP_IN_KENYA.HOW_CITIZEN', 'Thinks anyone who has lived in Kenya for many years becomes a citizen without applying.', '{"question":"A trader from another country has lived in Kenya for ten years. Is she now a Kenyan citizen?","wrong_answer":"Yes, automatically","correct_answer":"Only if she applies and is registered"}'::jsonb, 'The child thinks time alone turns a person into a citizen.', 'Offer "Yes, automatically" next to the right answer and ask the question again in a new context.', 'Read the rule: lawful residence for seven years lets a person apply to be registered.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G5.POLITI.CITIZENSHIP_IN_KENYA.DUAL.M_CZ_DUAL_TWO_KENYAS', 'SOCI.G5.POLITI.CITIZENSHIP_IN_KENYA.DUAL', 'Thinks dual citizenship means being a citizen of two counties.', '{"question":"What does dual citizenship mean?","wrong_answer":"Being from two counties","correct_answer":"Being a citizen of Kenya and of another country at the same time"}'::jsonb, 'County and country sound alike.', 'Offer "Being from two counties" next to the right answer and ask the question again in a new context.', 'Write county and country and say each with a map.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G5.POLITI.CITIZENSHIP_IN_KENYA.DUAL.M_CZ_DUAL_ANY_DUTY', 'SOCI.G5.POLITI.CITIZENSHIP_IN_KENYA.DUAL', 'Thinks a dual citizen has no duties to Kenya.', '{"question":"Does a dual citizen have to obey Kenya''s laws?","wrong_answer":"No, they belong to another country too","correct_answer":"Yes, they must obey Kenya''s laws"}'::jsonb, 'The child thinks the second country takes over.', 'Offer "No, they belong to another country too" next to the right answer and ask the question again in a new context.', 'Ask what happens when a dual citizen drives in Nairobi.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G5.POLITI.CITIZENSHIP_IN_KENYA.GOOD_CITIZEN.M_CZ_ADULTS_ONLY', 'SOCI.G5.POLITI.CITIZENSHIP_IN_KENYA.GOOD_CITIZEN', 'Thinks only adults can be good citizens.', '{"question":"Can a Grade 5 learner be a good citizen?","wrong_answer":"No, only adults","correct_answer":"Yes, by obeying rules, respecting others and caring for the environment"}'::jsonb, 'Voting is the duty the child hears about most.', 'Offer "No, only adults" next to the right answer and ask the question again in a new context.', 'List what a learner did this week that helps the country.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G5.POLITI.CITIZENSHIP_IN_KENYA.GOOD_CITIZEN.M_CZ_REPORT_WRONG_SELF', 'SOCI.G5.POLITI.CITIZENSHIP_IN_KENYA.GOOD_CITIZEN', 'Thinks a good citizen should punish wrongdoers themselves.', '{"question":"You see someone stealing a bicycle. What does a good citizen do?","wrong_answer":"Beat the thief","correct_answer":"Tell the police or a trusted adult"}'::jsonb, 'The child has seen crowds punishing suspects.', 'Offer "Beat the thief" next to the right answer and ask the question again in a new context.', 'Discuss why only the police and courts decide punishment.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G5.POLITI.NATIONAL_GOVERNMENT.ARMS_DUTIES.M_NG_ARM_MIX', 'SOCI.G5.POLITI.NATIONAL_GOVERNMENT.ARMS_DUTIES', 'Gives an arm the job of another (courts make laws; Parliament settles disputes).', '{"question":"Which arm of government makes laws?","wrong_answer":"The Judiciary","correct_answer":"The Legislature"}'::jsonb, 'The child knows three names but not which job goes with which.', 'Offer "The Judiciary" next to the right answer and ask the question again in a new context.', 'Use one verb per arm: runs, makes, explains.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G5.POLITI.NATIONAL_GOVERNMENT.ARMS_DUTIES.M_NG_PRESIDENT_ALL', 'SOCI.G5.POLITI.NATIONAL_GOVERNMENT.ARMS_DUTIES', 'Thinks the President alone makes laws, runs courts and the government.', '{"question":"Who makes laws for Kenya?","wrong_answer":"The President alone","correct_answer":"Parliament"}'::jsonb, 'The child thinks one person is in charge of everything.', 'Offer "The President alone" next to the right answer and ask the question again in a new context.', 'Show that each arm checks the others.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G5.POLITI.NATIONAL_GOVERNMENT.ARMS_MEMBERS.M_NG_MEMBER_MIX', 'SOCI.G5.POLITI.NATIONAL_GOVERNMENT.ARMS_MEMBERS', 'Puts a person in the wrong arm (a judge in the Executive, a minister in the Judiciary).', '{"question":"To which arm do judges belong?","wrong_answer":"The Executive","correct_answer":"The Judiciary"}'::jsonb, 'The child knows the people but not their arm.', 'Offer "The Executive" next to the right answer and ask the question again in a new context.', 'Place each title in one of three boxes by its job.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G5.POLITI.NATIONAL_GOVERNMENT.ARMS_MEMBERS.M_NG_COUNTY_NATIONAL', 'SOCI.G5.POLITI.NATIONAL_GOVERNMENT.ARMS_MEMBERS', 'Thinks governors and MCAs are part of the three arms of the National Government.', '{"question":"Which of these is part of the National Government''s Executive?","wrong_answer":"A county governor","correct_answer":"The Deputy President"}'::jsonb, 'The child merges county and national levels.', 'Offer "A county governor" next to the right answer and ask the question again in a new context.', 'Draw two levels: county and national.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G5.POLITI.NATIONAL_GOVERNMENT.ARMS_DUTIES.M_NG_TWO_ARMS', 'SOCI.G5.POLITI.NATIONAL_GOVERNMENT.ARMS_DUTIES', 'Names only two arms of government (the President and Parliament) and leaves out the courts.', '{"question":"How many arms does the National Government have?","wrong_answer":"Two: the President and Parliament","correct_answer":"Three: the Executive, the Legislature and the Judiciary"}'::jsonb, 'Courts are seldom shown with the government on the news.', 'Offer "Two: the President and Parliament" next to the right answer and ask the question again in a new context.', 'Draw the three boxes and put a judge''s gavel in the third.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G5.POLITI.NATIONAL_GOVERNMENT.ARMS_DUTIES.M_NG_POLICE_JUDGE', 'SOCI.G5.POLITI.NATIONAL_GOVERNMENT.ARMS_DUTIES', 'Thinks the police decide whether a person is guilty.', '{"question":"Who decides whether a person accused of stealing is guilty?","wrong_answer":"The police","correct_answer":"A court, in the Judiciary"}'::jsonb, 'The child sees the police arrest people and assumes they decide.', 'Offer "The police" next to the right answer and ask the question again in a new context.', 'Act it: the police arrest, the magistrate hears both sides and decides.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G5.POLITI.NATIONAL_GOVERNMENT.ARMS_MEMBERS.M_NG_SENATE_JUDICIARY', 'SOCI.G5.POLITI.NATIONAL_GOVERNMENT.ARMS_MEMBERS', 'Puts the Senate in the Judiciary.', '{"question":"In which arm is the Senate?","wrong_answer":"The Judiciary","correct_answer":"The Legislature"}'::jsonb, 'Senator sounds like a senior judge.', 'Offer "The Judiciary" next to the right answer and ask the question again in a new context.', 'Place the Senate card next to the National Assembly card in the Legislature box.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G5.POLITI.NATIONAL_GOVERNMENT.ARMS_MEMBERS.M_NG_CABINET_PARLIAMENT', 'SOCI.G5.POLITI.NATIONAL_GOVERNMENT.ARMS_MEMBERS', 'Puts Cabinet Secretaries in Parliament.', '{"question":"Are Cabinet Secretaries members of Parliament?","wrong_answer":"Yes, they sit in Parliament","correct_answer":"No, they are in the Executive"}'::jsonb, 'Cabinet Secretaries are seen answering questions in Parliament.', 'Offer "Yes, they sit in Parliament" next to the right answer and ask the question again in a new context.', 'Sort each office into the three boxes again with the rule: who carries out the law?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G5.GOVERN.NATIONAL_UNITY_IN_KENYA.SYMBOLS.M_NU_COLOUR_MEANING', 'SOCI.G5.GOVERN.NATIONAL_UNITY_IN_KENYA.SYMBOLS', 'Gives the flag colours the wrong meaning (black for the land, green for the people).', '{"question":"What does the red on the Kenyan flag stand for?","wrong_answer":"The people of Kenya","correct_answer":"The blood shed in the struggle for freedom"}'::jsonb, 'The child remembers the colours but not the order of meanings.', 'Offer "The people of Kenya" next to the right answer and ask the question again in a new context.', 'Use a sentence: black people, red blood, green land, white peace.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G5.GOVERN.NATIONAL_UNITY_IN_KENYA.SYMBOLS.M_NU_SYMBOL_MIX', 'SOCI.G5.GOVERN.NATIONAL_UNITY_IN_KENYA.SYMBOLS', 'Names something that is not a national symbol as one (Mount Kenya, a football team).', '{"question":"Which of these is a national symbol of Kenya?","wrong_answer":"The Safari Rally","correct_answer":"The national anthem"}'::jsonb, 'The child thinks anything famous is a symbol.', 'Offer "The Safari Rally" next to the right answer and ask the question again in a new context.', 'List the official symbols and ask if the rally is among them.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G5.GOVERN.NATIONAL_UNITY_IN_KENYA.UNITY_FACTORS.M_NU_UNITY_SAME', 'SOCI.G5.GOVERN.NATIONAL_UNITY_IN_KENYA.UNITY_FACTORS', 'Thinks unity means everyone must be the same or speak one language.', '{"question":"What does national unity mean?","wrong_answer":"Everyone is the same","correct_answer":"People of different communities live together in peace"}'::jsonb, 'The child hears unity as uniformity.', 'Offer "Everyone is the same" next to the right answer and ask the question again in a new context.', 'Ask whether a football team where all are the same does well.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G5.GOVERN.NATIONAL_UNITY_IN_KENYA.UNITY_FACTORS.M_NU_TRIBE_FIX', 'SOCI.G5.GOVERN.NATIONAL_UNITY_IN_KENYA.UNITY_FACTORS', 'Thinks tribalism is solved by ignoring it or by separating communities.', '{"question":"How can we overcome tribalism?","wrong_answer":"Keep communities apart","correct_answer":"Mix, share and respect all communities"}'::jsonb, 'The child thinks separation prevents quarrels.', 'Offer "Keep communities apart" next to the right answer and ask the question again in a new context.', 'Describe a school with mixed friends and a school with split groups.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G5.GOVERN.NATIONAL_UNITY_IN_KENYA.SYMBOLS.M_NU_ANTHEM_ANY_SONG', 'SOCI.G5.GOVERN.NATIONAL_UNITY_IN_KENYA.SYMBOLS', 'Thinks any patriotic song is the national anthem.', '{"question":"Which song is the national anthem of Kenya?","wrong_answer":"Any song about Kenya","correct_answer":"\"Ee Mungu Nguvu Yetu\""}'::jsonb, 'The child hears many patriotic songs at events.', 'Offer "Any song about Kenya" next to the right answer and ask the question again in a new context.', 'Sing the first line of the anthem and of another song and ask which is sung at the flag.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G5.GOVERN.NATIONAL_UNITY_IN_KENYA.SYMBOLS.M_NU_SHIELD_MEANING', 'SOCI.G5.GOVERN.NATIONAL_UNITY_IN_KENYA.SYMBOLS', 'Thinks the shield and spears on the flag stand for war against neighbours.', '{"question":"What do the shield and spears on the flag stand for?","wrong_answer":"War with other countries","correct_answer":"Defending Kenya''s freedom"}'::jsonb, 'The child links weapons with fighting others.', 'Offer "War with other countries" next to the right answer and ask the question again in a new context.', 'Ask what a shield does: it protects.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G5.GOVERN.NATIONAL_UNITY_IN_KENYA.UNITY_FACTORS.M_NU_SPORTS_NO', 'SOCI.G5.GOVERN.NATIONAL_UNITY_IN_KENYA.UNITY_FACTORS', 'Does not see sports and national days as things that unite people.', '{"question":"How do athletics races help unite Kenya?","wrong_answer":"They do not; they are just games","correct_answer":"People from all communities cheer for Kenya together"}'::jsonb, 'The child sees sport as entertainment only.', 'Offer "They do not; they are just games" next to the right answer and ask the question again in a new context.', 'Recall a race when everyone cheered a Kenyan winner.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G5.GOVERN.NATIONAL_UNITY_IN_KENYA.UNITY_FACTORS.M_NU_CORRUPTION_UNITY', 'SOCI.G5.GOVERN.NATIONAL_UNITY_IN_KENYA.UNITY_FACTORS', 'Does not see unfair sharing of resources as a challenge to unity.', '{"question":"How can unfair sharing of resources harm unity?","wrong_answer":"It cannot","correct_answer":"People who feel left out may stop trusting each other"}'::jsonb, 'The child sees unity only as a feeling between people.', 'Offer "It cannot" next to the right answer and ask the question again in a new context.', 'Share sweets unfairly in a game and ask how the group feels.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G5.GOVERN.HUMAN_RIGHTS.BASIC_RIGHTS.M_HR_WANT_AS_RIGHT', 'SOCI.G5.GOVERN.HUMAN_RIGHTS.BASIC_RIGHTS', 'Calls a want (a phone, sweets) a right.', '{"question":"Which is a human right?","wrong_answer":"A new phone","correct_answer":"Education"}'::jsonb, 'The child thinks anything wanted is a right.', 'Offer "A new phone" next to the right answer and ask the question again in a new context.', 'Sort cards into needs that protect life and dignity and things that are nice to have.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G5.GOVERN.HUMAN_RIGHTS.BASIC_RIGHTS.M_HR_ADULT_ONLY', 'SOCI.G5.GOVERN.HUMAN_RIGHTS.BASIC_RIGHTS', 'Thinks only adults have rights.', '{"question":"Who has the right to education?","wrong_answer":"Only adults","correct_answer":"Every child"}'::jsonb, 'The child sees rights as a grown-up matter.', 'Offer "Only adults" next to the right answer and ask the question again in a new context.', 'Read the children''s rights list aloud.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G5.GOVERN.HUMAN_RIGHTS.RIGHTS_RESPONSIBILITY.M_HR_NO_LIMIT', 'SOCI.G5.GOVERN.HUMAN_RIGHTS.RIGHTS_RESPONSIBILITY', 'Thinks a right allows someone to do anything, even if it harms another.', '{"question":"Eve says she has a right to play loud music at night. What is missing?","wrong_answer":"Nothing, she may do it","correct_answer":"Respecting the right of others to rest"}'::jsonb, 'The child sees rights only for himself.', 'Offer "Nothing, she may do it" next to the right answer and ask the question again in a new context.', 'Ask whose rights are touched when the music is loud.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G5.GOVERN.HUMAN_RIGHTS.RIGHTS_RESPONSIBILITY.M_HR_NO_REPORT', 'SOCI.G5.GOVERN.HUMAN_RIGHTS.RIGHTS_RESPONSIBILITY', 'Thinks a child who is abused should keep quiet because it is a family matter.', '{"question":"A child is beaten badly at home. What should another child do?","wrong_answer":"Keep quiet because it is a family matter","correct_answer":"Tell a trusted adult or call Childline 116"}'::jsonb, 'The child fears trouble for the family or for himself.', 'Offer "Keep quiet because it is a family matter" next to the right answer and ask the question again in a new context.', 'Practise telling a teacher and call Childline 116.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G5.GOVERN.HUMAN_RIGHTS.BASIC_RIGHTS.M_HR_EARNED', 'SOCI.G5.GOVERN.HUMAN_RIGHTS.BASIC_RIGHTS', 'Thinks rights must be earned by good behaviour.', '{"question":"Does a child lose the right to education for bad behaviour?","wrong_answer":"Yes, rights are earned","correct_answer":"No, every child has rights; bad behaviour has other consequences"}'::jsonb, 'The child confuses rights with privileges given as rewards.', 'Offer "Yes, rights are earned" next to the right answer and ask the question again in a new context.', 'Sort: break time football (privilege) and education (right).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G5.GOVERN.HUMAN_RIGHTS.BASIC_RIGHTS.M_HR_RICH_MORE', 'SOCI.G5.GOVERN.HUMAN_RIGHTS.BASIC_RIGHTS', 'Thinks rich people have more rights than poor people.', '{"question":"Do rich and poor children have the same rights?","wrong_answer":"No, rich children have more","correct_answer":"Yes, all children have the same rights"}'::jsonb, 'The child sees rich children with more things.', 'Offer "No, rich children have more" next to the right answer and ask the question again in a new context.', 'Separate things a family can buy from rights the law gives everyone.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G5.GOVERN.HUMAN_RIGHTS.RIGHTS_RESPONSIBILITY.M_HR_DUTY_MATCH', 'SOCI.G5.GOVERN.HUMAN_RIGHTS.RIGHTS_RESPONSIBILITY', 'Pairs a right with an unrelated responsibility (the right to education with keeping the compound clean).', '{"question":"Which responsibility goes with the right to education?","wrong_answer":"Sweeping the compound","correct_answer":"Attending school and doing your best"}'::jsonb, 'The child picks any duty they know.', 'Offer "Sweeping the compound" next to the right answer and ask the question again in a new context.', 'Pair each right with the duty that protects it for you and others.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G5.GOVERN.HUMAN_RIGHTS.RIGHTS_RESPONSIBILITY.M_HR_OTHERS_NOT', 'SOCI.G5.GOVERN.HUMAN_RIGHTS.RIGHTS_RESPONSIBILITY', 'Thinks protecting rights is only about your own rights, not other people''s.', '{"question":"Your right to speak means you should...","wrong_answer":"speak whenever you want","correct_answer":"speak and let others speak too"}'::jsonb, 'The child hears "my rights" more than "others'' rights".', 'Offer "speak whenever you want" next to the right answer and ask the question again in a new context.', 'Run a talk where only one learner may speak, then a fair turn-taking talk.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G5.GOVERN.DEMOCRACY_IN_SOCIETY.TYPES.M_DM_TYPE_MIX', 'SOCI.G5.GOVERN.DEMOCRACY_IN_SOCIETY.TYPES', 'Swaps direct and representative democracy.', '{"question":"The class votes by raising hands to choose a game. What type of democracy is this?","wrong_answer":"Representative democracy","correct_answer":"Direct democracy"}'::jsonb, 'The child knows the names but not the meaning.', 'Offer "Representative democracy" next to the right answer and ask the question again in a new context.', 'Ask: did each person decide, or did chosen people decide for them?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G5.GOVERN.DEMOCRACY_IN_SOCIETY.TYPES.M_DM_NOT_DEMOCRACY', 'SOCI.G5.GOVERN.DEMOCRACY_IN_SOCIETY.TYPES', 'Counts rule by one person as a type of democracy.', '{"question":"Which one is a democracy?","wrong_answer":"A leader who rules for life without elections","correct_answer":"Voters elect their leaders"}'::jsonb, 'The child thinks any government is a democracy.', 'Offer "A leader who rules for life without elections" next to the right answer and ask the question again in a new context.', 'Ask who chose the leader and who can remove him.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G5.GOVERN.DEMOCRACY_IN_SOCIETY.BENEFITS_PRACTICE.M_DM_MAJORITY_ALL', 'SOCI.G5.GOVERN.DEMOCRACY_IN_SOCIETY.BENEFITS_PRACTICE', 'Thinks that after a vote the minority no longer matters.', '{"question":"After the vote, 12 learners chose football and 8 chose netball. What is fair?","wrong_answer":"The 8 learners are ignored","correct_answer":"Football is played, and the 8 are still respected"}'::jsonb, 'The child thinks winning means the others lose everything.', 'Offer "The 8 learners are ignored" next to the right answer and ask the question again in a new context.', 'Ask how the 8 can still get a turn another day.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G5.GOVERN.DEMOCRACY_IN_SOCIETY.BENEFITS_PRACTICE.M_DM_LOUDEST', 'SOCI.G5.GOVERN.DEMOCRACY_IN_SOCIETY.BENEFITS_PRACTICE', 'Thinks the loudest candidate or the one the teacher likes should win.', '{"question":"What is the fair way to choose a class monitor?","wrong_answer":"The loudest learner is chosen","correct_answer":"Learners vote in secret and the votes are counted"}'::jsonb, 'The child sees choice as who is strongest.', 'Offer "The loudest learner is chosen" next to the right answer and ask the question again in a new context.', 'Run a mock election with secret ballots.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G5.GOVERN.DEMOCRACY_IN_SOCIETY.TYPES.M_DM_REFERENDUM', 'SOCI.G5.GOVERN.DEMOCRACY_IN_SOCIETY.TYPES', 'Does not see a referendum as direct democracy.', '{"question":"In a referendum all voters decide on a law themselves. What type of democracy is this?","wrong_answer":"Representative democracy","correct_answer":"Direct democracy"}'::jsonb, 'The child links all national voting with electing leaders.', 'Offer "Representative democracy" next to the right answer and ask the question again in a new context.', 'Compare: electing an MP (someone decides for you) and a referendum (you decide).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G5.GOVERN.DEMOCRACY_IN_SOCIETY.TYPES.M_DM_VOTING_ONLY', 'SOCI.G5.GOVERN.DEMOCRACY_IN_SOCIETY.TYPES', 'Thinks democracy is only voting and nothing else.', '{"question":"Is speaking at a public meeting about a new road part of democracy?","wrong_answer":"No, democracy is only voting","correct_answer":"Yes, it is public participation"}'::jsonb, 'Voting is the most taught example.', 'Offer "No, democracy is only voting" next to the right answer and ask the question again in a new context.', 'List other ways people take part: meetings, petitions, peaceful protest.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G5.GOVERN.DEMOCRACY_IN_SOCIETY.BENEFITS_PRACTICE.M_DM_BRIBE_FAIR', 'SOCI.G5.GOVERN.DEMOCRACY_IN_SOCIETY.BENEFITS_PRACTICE', 'Thinks giving voters gifts or money is a fair campaign.', '{"question":"A candidate gives voters money for their votes. Is this fair?","wrong_answer":"Yes, it helps people","correct_answer":"No, it is bribery and breaks free choice"}'::jsonb, 'Gifts feel kind to the child.', 'Offer "Yes, it helps people" next to the right answer and ask the question again in a new context.', 'Ask whether people would vote for the best leader or for the money.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G5.GOVERN.DEMOCRACY_IN_SOCIETY.BENEFITS_PRACTICE.M_DM_RESULT_FIGHT', 'SOCI.G5.GOVERN.DEMOCRACY_IN_SOCIETY.BENEFITS_PRACTICE', 'Thinks losers should fight if they do not like the result.', '{"question":"A candidate lost. What is the fair way to respond?","wrong_answer":"Fight the winner","correct_answer":"Accept the result or take a complaint to the right body peacefully"}'::jsonb, 'The child has heard of election violence.', 'Offer "Fight the winner" next to the right answer and ask the question again in a new context.', 'Discuss the peaceful ways to complain: courts, the electoral body.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
